 SetPixelAlpha ( image , ClampToQuantum ( pixel ) , q ) ;
 p += quantum_info -> pad ;
 q += GetPixelChannels ( image ) ;
 }
 break ;
 }
 }
 default : {
 range = GetQuantumRange ( quantum_info -> depth ) ;
 for ( x = 0 ;
 x < ( ssize_t ) number_pixels ;
 x ++ ) {
 p = PushQuantumPixel ( quantum_info , p , & pixel ) ;
 SetPixelGray ( image , ScaleAnyToQuantum ( pixel , range ) , q ) ;
 p = PushQuantumPixel ( quantum_info , p , & pixel ) ;
 SetPixelAlpha ( image , ScaleAnyToQuantum ( pixel , range ) , q ) ;
 p += quantum_info -> pad ;
 q += GetPixelChannels ( image ) ;
 }
 break ;
 }
 }
 }

static void pmac_ide_writeb ( void * opaque , hwaddr addr , uint32_t val ) {
 MACIOIDEState * d = opaque ;
 addr = ( addr & 0xFFF ) >> 4 ;
 switch ( addr ) {
 case 1 ... 7 : ide_ioport_write ( & d -> bus , addr , val ) ;
 break ;
 case 8 : case 22 : ide_cmd_write ( & d -> bus , 0 , val ) ;
 break ;
 default : break ;
 }
 }

static void cirrus_mmio_write ( void * opaque , hwaddr addr , uint64_t val , unsigned size ) {
 CirrusVGAState * s = opaque ;
 if ( addr >= 0x100 ) {
 cirrus_mmio_blt_write ( s , addr - 0x100 , val ) ;
 }
 else {
 cirrus_vga_ioport_write ( s , addr + 0x10 , val , size ) ;
 }
 }

static inline hwaddr prep_IO_address ( sysctrl_t * sysctrl , hwaddr addr ) {
 if ( sysctrl -> contiguous_map == 0 ) {
 addr &= 0xFFFF ;
 }
 else {
 addr = ( addr & 0x1F ) | ( ( addr & 0x007FFF000 ) >> 7 ) ;
 }
 return addr ;
 }

static uint64_t cirrus_mmio_read ( void * opaque , hwaddr addr , unsigned size ) {
 CirrusVGAState * s = opaque ;
 if ( addr >= 0x100 ) {
 return cirrus_mmio_blt_read ( s , addr - 0x100 ) ;
 }
 else {
 return cirrus_vga_ioport_read ( s , addr + 0x10 , size ) ;
 }
 }

