 if ( top_level && expr -> nulltesttype == IS_NOT_NULL && ! expr -> argisrow ) result = find_nonnullable_vars_walker ( ( Node * ) expr -> arg , false ) ;
 }
 else if ( IsA ( node , BooleanTest ) ) {
