 while ( p_owner -> b_flushing ) vlc_cond_wait ( & p_owner -> wait_acknowledge , & p_owner -> lock ) ;
 }

void input_DecoderStartWait ( decoder_t * p_dec ) {
 decoder_owner_sys_t * p_owner = p_dec -> p_owner ;
 vlc_mutex_lock ( & p_owner -> lock ) ;
