static void update_mbgraph_frame_stats ( VP9_COMP * cpi , MBGRAPH_FRAME_STATS * stats , YV12_BUFFER_CONFIG * buf , YV12_BUFFER_CONFIG * golden_ref , YV12_BUFFER_CONFIG * alt_ref ) {
 MACROBLOCK * const x = & cpi -> mb ;
 MACROBLOCKD * const xd = & x -> e_mbd ;
 VP9_COMMON * const cm = & cpi -> common ;
 int mb_col , mb_row , offset = 0 ;
 int mb_y_offset = 0 , arf_y_offset = 0 , gld_y_offset = 0 ;
 MV gld_top_mv = {
 0 , 0 }
 ;
 MODE_INFO mi_local ;
 vp9_zero ( mi_local ) ;
 x -> mv_row_min = - BORDER_MV_PIXELS_B16 ;
 x -> mv_row_max = ( cm -> mb_rows - 1 ) * 8 + BORDER_MV_PIXELS_B16 ;
 xd -> up_available = 0 ;
 xd -> plane [ 0 ] . dst . stride = buf -> y_stride ;
 xd -> plane [ 0 ] . pre [ 0 ] . stride = buf -> y_stride ;
 xd -> plane [ 1 ] . dst . stride = buf -> uv_stride ;
 xd -> mi [ 0 ] . src_mi = & mi_local ;
 mi_local . mbmi . sb_type = BLOCK_16X16 ;
 mi_local . mbmi . ref_frame [ 0 ] = LAST_FRAME ;
 mi_local . mbmi . ref_frame [ 1 ] = NONE ;
 for ( mb_row = 0 ;
 mb_row < cm -> mb_rows ;
 mb_row ++ ) {
 MV gld_left_mv = gld_top_mv ;
 int mb_y_in_offset = mb_y_offset ;
 int arf_y_in_offset = arf_y_offset ;
 int gld_y_in_offset = gld_y_offset ;
 x -> mv_col_min = - BORDER_MV_PIXELS_B16 ;
 x -> mv_col_max = ( cm -> mb_cols - 1 ) * 8 + BORDER_MV_PIXELS_B16 ;
 xd -> left_available = 0 ;
 for ( mb_col = 0 ;
 mb_col < cm -> mb_cols ;
 mb_col ++ ) {
 MBGRAPH_MB_STATS * mb_stats = & stats -> mb_stats [ offset + mb_col ] ;
 update_mbgraph_mb_stats ( cpi , mb_stats , buf , mb_y_in_offset , golden_ref , & gld_left_mv , alt_ref , mb_row , mb_col ) ;
 gld_left_mv = mb_stats -> ref [ GOLDEN_FRAME ] . m . mv . as_mv ;
 if ( mb_col == 0 ) {
 gld_top_mv = gld_left_mv ;
 }
 xd -> left_available = 1 ;
 mb_y_in_offset += 16 ;
 gld_y_in_offset += 16 ;
 arf_y_in_offset += 16 ;
 x -> mv_col_min -= 16 ;
 x -> mv_col_max -= 16 ;
 }
 xd -> up_available = 1 ;
 mb_y_offset += buf -> y_stride * 16 ;
 gld_y_offset += golden_ref -> y_stride * 16 ;
 if ( alt_ref ) arf_y_offset += alt_ref -> y_stride * 16 ;
 x -> mv_row_min -= 16 ;
 x -> mv_row_max -= 16 ;
 offset += cm -> mb_cols ;
 }
 }

static int64_t rd_pick_intra_sby_mode ( VP9_COMP * cpi , MACROBLOCK * x , int * rate , int * rate_tokenonly , int64_t * distortion , int * skippable , BLOCK_SIZE bsize , int64_t tx_cache [ TX_MODES ] , int64_t best_rd ) {
 PREDICTION_MODE mode ;
 PREDICTION_MODE mode_selected = DC_PRED ;
 MACROBLOCKD * const xd = & x -> e_mbd ;
 MODE_INFO * const mic = xd -> mi [ 0 ] . src_mi ;
 int this_rate , this_rate_tokenonly , s ;
 int64_t this_distortion , this_rd ;
 TX_SIZE best_tx = TX_4X4 ;
 int i ;
 int * bmode_costs = cpi -> mbmode_cost ;
 if ( cpi -> sf . tx_size_search_method == USE_FULL_RD ) for ( i = 0 ;
 i < TX_MODES ;
 i ++ ) tx_cache [ i ] = INT64_MAX ;
 for ( mode = DC_PRED ;
 mode <= TM_PRED ;
 mode ++ ) {
 int64_t local_tx_cache [ TX_MODES ] ;
 MODE_INFO * above_mi = xd -> mi [ - xd -> mi_stride ] . src_mi ;
 MODE_INFO * left_mi = xd -> left_available ? xd -> mi [ - 1 ] . src_mi : NULL ;
 if ( cpi -> common . frame_type == KEY_FRAME ) {
 const PREDICTION_MODE A = vp9_above_block_mode ( mic , above_mi , 0 ) ;
 const PREDICTION_MODE L = vp9_left_block_mode ( mic , left_mi , 0 ) ;
 bmode_costs = cpi -> y_mode_costs [ A ] [ L ] ;
 }
 mic -> mbmi . mode = mode ;
 super_block_yrd ( cpi , x , & this_rate_tokenonly , & this_distortion , & s , NULL , bsize , local_tx_cache , best_rd ) ;
 if ( this_rate_tokenonly == INT_MAX ) continue ;
 this_rate = this_rate_tokenonly + bmode_costs [ mode ] ;
 this_rd = RDCOST ( x -> rdmult , x -> rddiv , this_rate , this_distortion ) ;
 if ( this_rd < best_rd ) {
 mode_selected = mode ;
 best_rd = this_rd ;
 best_tx = mic -> mbmi . tx_size ;
 * rate = this_rate ;
 * rate_tokenonly = this_rate_tokenonly ;
 * distortion = this_distortion ;
 * skippable = s ;
 }
 if ( cpi -> sf . tx_size_search_method == USE_FULL_RD && this_rd < INT64_MAX ) {
 for ( i = 0 ;
 i < TX_MODES && local_tx_cache [ i ] < INT64_MAX ;
 i ++ ) {
 const int64_t adj_rd = this_rd + local_tx_cache [ i ] - local_tx_cache [ cpi -> common . tx_mode ] ;
 if ( adj_rd < tx_cache [ i ] ) {
 tx_cache [ i ] = adj_rd ;
 }
 }
 }
 }
 mic -> mbmi . mode = mode_selected ;
 mic -> mbmi . tx_size = best_tx ;
 return best_rd ;
 }

void vp9_model_rd_from_var_lapndz ( unsigned int var , unsigned int n , unsigned int qstep , int * rate , int64_t * dist ) {
 if ( var == 0 ) {
 * rate = 0 ;
 * dist = 0 ;
 }
 else {
 int d_q10 , r_q10 ;
 static const uint32_t MAX_XSQ_Q10 = 245727 ;
 const uint64_t xsq_q10_64 = ( ( ( ( uint64_t ) qstep * qstep * n ) << 10 ) + ( var >> 1 ) ) / var ;
 const int xsq_q10 = ( int ) MIN ( xsq_q10_64 , MAX_XSQ_Q10 ) ;
 model_rd_norm ( xsq_q10 , & r_q10 , & d_q10 ) ;
 * rate = ( n * r_q10 + 2 ) >> 2 ;
 * dist = ( var * ( int64_t ) d_q10 + 512 ) >> 10 ;
 }
 }

void vp9_update_layer_context_change_config ( VP9_COMP * const cpi , const int target_bandwidth ) {
 SVC * const svc = & cpi -> svc ;
 const VP9EncoderConfig * const oxcf = & cpi -> oxcf ;
 const RATE_CONTROL * const rc = & cpi -> rc ;
 int layer ;
 int layer_end ;
 float bitrate_alloc = 1.0 ;
 if ( svc -> number_temporal_layers > 1 && cpi -> oxcf . rc_mode == VPX_CBR ) {
 layer_end = svc -> number_temporal_layers ;
 }
 else {
 layer_end = svc -> number_spatial_layers ;
 }
 for ( layer = 0 ;
 layer < layer_end ;
 ++ layer ) {
 LAYER_CONTEXT * const lc = & svc -> layer_context [ layer ] ;
 RATE_CONTROL * const lrc = & lc -> rc ;
 if ( svc -> number_temporal_layers > 1 && cpi -> oxcf . rc_mode == VPX_CBR ) {
 lc -> target_bandwidth = oxcf -> ts_target_bitrate [ layer ] ;
 }
 else {
 lc -> target_bandwidth = oxcf -> ss_target_bitrate [ layer ] ;
 }
 bitrate_alloc = ( float ) lc -> target_bandwidth / target_bandwidth ;
 lrc -> starting_buffer_level = ( int64_t ) ( rc -> starting_buffer_level * bitrate_alloc ) ;
 lrc -> optimal_buffer_level = ( int64_t ) ( rc -> optimal_buffer_level * bitrate_alloc ) ;
 lrc -> maximum_buffer_size = ( int64_t ) ( rc -> maximum_buffer_size * bitrate_alloc ) ;
 lrc -> bits_off_target = MIN ( lrc -> bits_off_target , lrc -> maximum_buffer_size ) ;
 lrc -> buffer_level = MIN ( lrc -> buffer_level , lrc -> maximum_buffer_size ) ;
 if ( svc -> number_temporal_layers > 1 && cpi -> oxcf . rc_mode == VPX_CBR ) {
 lc -> framerate = cpi -> framerate / oxcf -> ts_rate_decimator [ layer ] ;
 }
 else {
 lc -> framerate = cpi -> framerate ;
 }
 lrc -> avg_frame_bandwidth = ( int ) ( lc -> target_bandwidth / lc -> framerate ) ;
 lrc -> max_frame_bandwidth = rc -> max_frame_bandwidth ;
 lrc -> worst_quality = rc -> worst_quality ;
 lrc -> best_quality = rc -> best_quality ;
 }
 }

