 }
 }
 else {
 input [ 0 ] = in [ 0 * 4 ] ;
 input [ 1 ] = in [ 1 * 4 ] ;
 input [ 2 ] = in [ 2 * 4 ] ;
 input [ 3 ] = in [ 3 * 4 ] ;
