 temp2 = - step [ 2 ] * cospi_8_64 + step [ 3 ] * cospi_24_64 ;
 out [ 1 ] = fdct_round_shift ( temp1 ) ;
 out [ 3 ] = fdct_round_shift ( temp2 ) ;
