 if ( ( ret = ff_get_buffer ( avctx , frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "Me fail get_buffer()? That's unpossible!\n" ) ;
 return ret ;
 }
 samples0 = ( int16_t * ) frame -> data [ 0 ] ;
 samples1 = ( int16_t * ) frame -> data [ 1 ] ;
 if ( src_size < 5 ) {
 av_log ( avctx , AV_LOG_ERROR , "too short packets are too short!\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 table_size = AV_RB16 ( src ) ;
 table_bytes = ( table_size + 7 ) >> 3 ;
 if ( src_size < table_bytes + 3 ) {
 av_log ( avctx , AV_LOG_ERROR , "short packets are short!\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 init_get_bits ( & gb , src + 2 , table_size ) ;
 ctx -> num_blocks = 0 ;
 while ( get_bits_left ( & gb ) > 0 ) {
 ctx -> block_size [ ctx -> num_blocks ] = get_bits ( & gb , 15 ) ;
 if ( get_bits1 ( & gb ) ) {
 ctx -> block_pts [ ctx -> num_blocks ] = get_bits ( & gb , 9 ) ;
 }
 else {
 ctx -> block_pts [ ctx -> num_blocks ] = 0 ;
 }
 ctx -> num_blocks ++ ;
 }
 block_pointer = src + table_bytes + 2 ;
 bytes_left = src_size - table_bytes - 2 ;
 ctx -> sample_offset = 0 ;
 for ( i = 0 ;
 i < ctx -> num_blocks ;
 i ++ ) {
 if ( bytes_left < ctx -> block_size [ i ] ) {
 av_log ( avctx , AV_LOG_ERROR , "I'm pedaling backwards\n" ) ;
 break ;
 }
 init_get_bits ( & gb , block_pointer , ctx -> block_size [ i ] * 8 ) ;
 if ( decode_block ( avctx , & gb , samples0 + ctx -> sample_offset , samples1 + ctx -> sample_offset ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "Sir, I got carsick in your office. Not decoding the rest of packet.\n" ) ;
 break ;
 }
 block_pointer += ctx -> block_size [ i ] ;
 bytes_left -= ctx -> block_size [ i ] ;
 }
 frame -> nb_samples = ctx -> sample_offset ;
 * got_frame_ptr = ctx -> sample_offset > 0 ;
 return avpkt -> size ;
 }

static void apply_pitch_filters ( QCELPContext * q , float * cdn_vector ) {
 int i ;
 const float * v_synthesis_filtered , * v_pre_filtered ;
 if ( q -> bitrate >= RATE_HALF || q -> bitrate == SILENCE || ( q -> bitrate == I_F_Q && ( q -> prev_bitrate >= RATE_HALF ) ) ) {
 if ( q -> bitrate >= RATE_HALF ) {
 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 q -> pitch_gain [ i ] = q -> frame . plag [ i ] ? ( q -> frame . pgain [ i ] + 1 ) * 0.25 : 0.0 ;
 q -> pitch_lag [ i ] = q -> frame . plag [ i ] + 16 ;
 }
 }
 else {
 float max_pitch_gain ;
 if ( q -> bitrate == I_F_Q ) {
 if ( q -> erasure_count < 3 ) max_pitch_gain = 0.9 - 0.3 * ( q -> erasure_count - 1 ) ;
 else max_pitch_gain = 0.0 ;
 }
 else {
 assert ( q -> bitrate == SILENCE ) ;
 max_pitch_gain = 1.0 ;
 }
 for ( i = 0 ;
 i < 4 ;
 i ++ ) q -> pitch_gain [ i ] = FFMIN ( q -> pitch_gain [ i ] , max_pitch_gain ) ;
 memset ( q -> frame . pfrac , 0 , sizeof ( q -> frame . pfrac ) ) ;
 }
 v_synthesis_filtered = do_pitchfilter ( q -> pitch_synthesis_filter_mem , cdn_vector , q -> pitch_gain , q -> pitch_lag , q -> frame . pfrac ) ;
 for ( i = 0 ;
 i < 4 ;
 i ++ ) q -> pitch_gain [ i ] = 0.5 * FFMIN ( q -> pitch_gain [ i ] , 1.0 ) ;
 v_pre_filtered = do_pitchfilter ( q -> pitch_pre_filter_mem , v_synthesis_filtered , q -> pitch_gain , q -> pitch_lag , q -> frame . pfrac ) ;
 apply_gain_ctrl ( cdn_vector , v_synthesis_filtered , v_pre_filtered ) ;
 }
 else {
 memcpy ( q -> pitch_synthesis_filter_mem , cdn_vector + 17 , 143 * sizeof ( float ) ) ;
 memcpy ( q -> pitch_pre_filter_mem , cdn_vector + 17 , 143 * sizeof ( float ) ) ;
 memset ( q -> pitch_gain , 0 , sizeof ( q -> pitch_gain ) ) ;
 memset ( q -> pitch_lag , 0 , sizeof ( q -> pitch_lag ) ) ;
 }
 }

static int svq3_decode_slice_header ( AVCodecContext * avctx ) {
 SVQ3Context * s = avctx -> priv_data ;
 H264Context * h = & s -> h ;
 const int mb_xy = h -> mb_xy ;
 int i , header ;
 unsigned slice_id ;
 header = get_bits ( & h -> gb , 8 ) ;
 if ( ( ( header & 0x9F ) != 1 && ( header & 0x9F ) != 2 ) || ( header & 0x60 ) == 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "unsupported slice header (%02X)\n" , header ) ;
 return - 1 ;
 }
 else {
 int length = header >> 5 & 3 ;
 s -> next_slice_index = get_bits_count ( & h -> gb ) + 8 * show_bits ( & h -> gb , 8 * length ) + 8 * length ;
 if ( s -> next_slice_index > h -> gb . size_in_bits ) {
 av_log ( avctx , AV_LOG_ERROR , "slice after bitstream end\n" ) ;
 return - 1 ;
 }
 h -> gb . size_in_bits = s -> next_slice_index - 8 * ( length - 1 ) ;
 skip_bits ( & h -> gb , 8 ) ;
 if ( s -> watermark_key ) {
 uint32_t header = AV_RL32 ( & h -> gb . buffer [ ( get_bits_count ( & h -> gb ) >> 3 ) + 1 ] ) ;
 AV_WL32 ( & h -> gb . buffer [ ( get_bits_count ( & h -> gb ) >> 3 ) + 1 ] , header ^ s -> watermark_key ) ;
 }
 if ( length > 0 ) {
 memcpy ( ( uint8_t * ) & h -> gb . buffer [ get_bits_count ( & h -> gb ) >> 3 ] , & h -> gb . buffer [ h -> gb . size_in_bits >> 3 ] , length - 1 ) ;
 }
 skip_bits_long ( & h -> gb , 0 ) ;
 }
 if ( ( slice_id = svq3_get_ue_golomb ( & h -> gb ) ) >= 3 ) {
 av_log ( h -> avctx , AV_LOG_ERROR , "illegal slice type %d \n" , slice_id ) ;
 return - 1 ;
 }
 h -> slice_type = golomb_to_pict_type [ slice_id ] ;
 if ( ( header & 0x9F ) == 2 ) {
 i = ( h -> mb_num < 64 ) ? 6 : ( 1 + av_log2 ( h -> mb_num - 1 ) ) ;
 h -> mb_skip_run = get_bits ( & h -> gb , i ) - ( h -> mb_y * h -> mb_width + h -> mb_x ) ;
 }
 else {
 skip_bits1 ( & h -> gb ) ;
 h -> mb_skip_run = 0 ;
 }
 h -> slice_num = get_bits ( & h -> gb , 8 ) ;
 h -> qscale = get_bits ( & h -> gb , 5 ) ;
 s -> adaptive_quant = get_bits1 ( & h -> gb ) ;
 skip_bits1 ( & h -> gb ) ;
 if ( s -> unknown_flag ) skip_bits1 ( & h -> gb ) ;
 skip_bits1 ( & h -> gb ) ;
 skip_bits ( & h -> gb , 2 ) ;
 while ( get_bits1 ( & h -> gb ) ) skip_bits ( & h -> gb , 8 ) ;
 if ( h -> mb_x > 0 ) {
 memset ( h -> intra4x4_pred_mode + h -> mb2br_xy [ mb_xy - 1 ] + 3 , - 1 , 4 * sizeof ( int8_t ) ) ;
 memset ( h -> intra4x4_pred_mode + h -> mb2br_xy [ mb_xy - h -> mb_x ] , - 1 , 8 * sizeof ( int8_t ) * h -> mb_x ) ;
 }
 if ( h -> mb_y > 0 ) {
 memset ( h -> intra4x4_pred_mode + h -> mb2br_xy [ mb_xy - h -> mb_stride ] , - 1 , 8 * sizeof ( int8_t ) * ( h -> mb_width - h -> mb_x ) ) ;
 if ( h -> mb_x > 0 ) h -> intra4x4_pred_mode [ h -> mb2br_xy [ mb_xy - h -> mb_stride - 1 ] + 3 ] = - 1 ;
 }
 return 0 ;
 }

