 }
 out = ctx -> pic . data [ 0 ] ;
 src = ctx -> cur ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 memcpy ( out , src , avctx -> width ) ;
 src += 320 ;
 out += ctx -> pic . linesize [ 0 ] ;
 }
 if ( ctx -> cur == ctx -> frm0 ) {
 ctx -> cur = ctx -> frm1 ;
 ctx -> prev = ctx -> frm0 ;
 }
 else {
 ctx -> cur = ctx -> frm0 ;
 ctx -> prev = ctx -> frm1 ;
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = ctx -> pic ;
