 xd -> mi [ 0 ] -> mbmi . tx_size = TX_4X4 ;
 for ( mode = DC_PRED ;
 mode <= TM_PRED ;
 ++ mode ) {
 int64_t this_rd ;
 int ratey = 0 ;
