 q_adj_factor -= 0.25 ;
 }
 q_val = vp9_convert_qindex_to_q ( active_best_quality ) ;
 active_best_quality += vp9_compute_qdelta ( rc , q_val , q_val * q_adj_factor ) ;
 }
 }
 else if ( ! rc -> is_src_frame_alt_ref && ( cpi -> refresh_golden_frame || cpi -> refresh_alt_ref_frame ) ) {
