 if ( q < cq_level ) q = cq_level ;
 active_best_quality = get_gf_active_quality ( rc , q ) ;
 active_best_quality = active_best_quality * 15 / 16 ;
 }
 else if ( oxcf -> rc_mode == VPX_Q ) {
 if ( ! cpi -> refresh_alt_ref_frame ) {
 active_best_quality = cq_level ;
 }
 else {
 active_best_quality = get_gf_active_quality ( rc , q ) ;
 }
 }
 else {
 active_best_quality = get_gf_active_quality ( rc , q ) ;
 }
 }
