static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 JvContext * s = avctx -> priv_data ;
 int buf_size = avpkt -> size ;
 const uint8_t * buf = avpkt -> data ;
 const uint8_t * buf_end = buf + buf_size ;
 int video_size , video_type , i , j , ret ;
 video_size = AV_RL32 ( buf ) ;
 video_type = buf [ 4 ] ;
 buf += 5 ;
 if ( video_size ) {
 if ( ( ret = ff_reget_buffer ( avctx , & s -> frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 if ( video_type == 0 || video_type == 1 ) {
 GetBitContext gb ;
 init_get_bits ( & gb , buf , 8 * FFMIN ( video_size , buf_end - buf ) ) ;
 for ( j = 0 ;
 j < avctx -> height ;
 j += 8 ) for ( i = 0 ;
 i < avctx -> width ;
 i += 8 ) decode8x8 ( & gb , s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] + i , s -> frame . linesize [ 0 ] , & s -> dsp ) ;
 buf += video_size ;
 }
 else if ( video_type == 2 ) {
 if ( buf + 1 <= buf_end ) {
 int v = * buf ++ ;
 for ( j = 0 ;
 j < avctx -> height ;
 j ++ ) memset ( s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] , v , avctx -> width ) ;
 }
 }
 else {
 av_log ( avctx , AV_LOG_WARNING , "unsupported frame type %i\n" , video_type ) ;
 return AVERROR_INVALIDDATA ;
 }
 }
 if ( buf < buf_end ) {
 for ( i = 0 ;
 i < AVPALETTE_COUNT && buf + 3 <= buf_end ;
 i ++ ) {
 s -> palette [ i ] = AV_RB24 ( buf ) << 2 ;
 buf += 3 ;
 }
 s -> palette_has_changed = 1 ;
 }
 if ( video_size ) {
 s -> frame . key_frame = 1 ;
 s -> frame . pict_type = AV_PICTURE_TYPE_I ;
 s -> frame . palette_has_changed = s -> palette_has_changed ;
 s -> palette_has_changed = 0 ;
 memcpy ( s -> frame . data [ 1 ] , s -> palette , AVPALETTE_SIZE ) ;
 if ( ( ret = av_frame_ref ( data , & s -> frame ) ) < 0 ) return ret ;
 * got_frame = 1 ;
 }
 return buf_size ;
 }

static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 KmvcContext * const ctx = avctx -> priv_data ;
 AVFrame * frame = data ;
 uint8_t * out , * src ;
 int i , ret ;
 int header ;
 int blocksize ;
 const uint8_t * pal = av_packet_get_side_data ( avpkt , AV_PKT_DATA_PALETTE , NULL ) ;
 bytestream2_init ( & ctx -> g , avpkt -> data , avpkt -> size ) ;
 if ( ( ret = ff_get_buffer ( avctx , frame , 0 ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 header = bytestream2_get_byte ( & ctx -> g ) ;
 if ( bytestream2_peek_byte ( & ctx -> g ) == 127 ) {
 bytestream2_skip ( & ctx -> g , 3 ) ;
 for ( i = 0 ;
 i < 127 ;
 i ++ ) {
 ctx -> pal [ i + ( header & 0x81 ) ] = bytestream2_get_be24 ( & ctx -> g ) ;
 bytestream2_skip ( & ctx -> g , 1 ) ;
 }
 bytestream2_seek ( & ctx -> g , - 127 * 4 - 3 , SEEK_CUR ) ;
 }
 if ( header & KMVC_KEYFRAME ) {
 frame -> key_frame = 1 ;
 frame -> pict_type = AV_PICTURE_TYPE_I ;
 }
 else {
 frame -> key_frame = 0 ;
 frame -> pict_type = AV_PICTURE_TYPE_P ;
 }
 if ( header & KMVC_PALETTE ) {
 frame -> palette_has_changed = 1 ;
 for ( i = 1 ;
 i <= ctx -> palsize ;
 i ++ ) {
 ctx -> pal [ i ] = bytestream2_get_be24 ( & ctx -> g ) ;
 }
 }
 if ( pal ) {
 frame -> palette_has_changed = 1 ;
 memcpy ( ctx -> pal , pal , AVPALETTE_SIZE ) ;
 }
 if ( ctx -> setpal ) {
 ctx -> setpal = 0 ;
 frame -> palette_has_changed = 1 ;
 }
 memcpy ( frame -> data [ 1 ] , ctx -> pal , 1024 ) ;
 blocksize = bytestream2_get_byte ( & ctx -> g ) ;
 if ( blocksize != 8 && blocksize != 127 ) {
 av_log ( avctx , AV_LOG_ERROR , "Block size = %i\n" , blocksize ) ;
 return AVERROR_INVALIDDATA ;
 }
 memset ( ctx -> cur , 0 , 320 * 200 ) ;
 switch ( header & KMVC_METHOD ) {
 case 0 : case 1 : memcpy ( ctx -> cur , ctx -> prev , 320 * 200 ) ;
 break ;
 case 3 : kmvc_decode_intra_8x8 ( ctx , avctx -> width , avctx -> height ) ;
 break ;
 case 4 : kmvc_decode_inter_8x8 ( ctx , avctx -> width , avctx -> height ) ;
 break ;
 default : av_log ( avctx , AV_LOG_ERROR , "Unknown compression method %i\n" , header & KMVC_METHOD ) ;
 return AVERROR_INVALIDDATA ;
 }
 out = frame -> data [ 0 ] ;
 src = ctx -> cur ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 memcpy ( out , src , avctx -> width ) ;
 src += 320 ;
 out += frame -> linesize [ 0 ] ;
 }
 if ( ctx -> cur == ctx -> frm0 ) {
 ctx -> cur = ctx -> frm1 ;
 ctx -> prev = ctx -> frm0 ;
 }
 else {
 ctx -> cur = ctx -> frm0 ;
 ctx -> prev = ctx -> frm1 ;
 }
 * got_frame = 1 ;
 return avpkt -> size ;
 }

