 else {
 for ( ;
 len > 0 ;
 len -- ) {
 if ( a -> data [ len - 1 ] ) break ;
 }
 j = a -> data [ len - 1 ] ;
 if ( j & 0x01 ) bits = 0 ;
 else if ( j & 0x02 ) bits = 1 ;
 else if ( j & 0x04 ) bits = 2 ;
 else if ( j & 0x08 ) bits = 3 ;
 else if ( j & 0x10 ) bits = 4 ;
