 else s -> status [ 1 ] &= ~ ( 1 << 2 ) ;
 if ( s -> control [ 0 ] & ( 1 << 4 ) ) s -> status [ 1 ] |= 1 << 0 ;
 else s -> status [ 1 ] &= ~ ( 1 << 0 ) ;
 intr |= ( s -> control [ 0 ] & ( 1 << 5 ) ) && ( s -> status [ 0 ] & ( 1 << 4 ) ) ;
 intr |= ( s -> control [ 0 ] & ( 1 << 6 ) ) && ( s -> status [ 0 ] & ( 1 << 3 ) ) ;
