void vp9_model_rd_from_var_lapndz ( unsigned int var , unsigned int n , unsigned int qstep , int * rate , int64_t * dist ) {
 if ( var == 0 ) {
 * rate = 0 ;
 * dist = 0 ;
 }
 else {
