 be32_to_cpus ( & ext . magic ) ;
 be32_to_cpus ( & ext . len ) ;
 offset += sizeof ( ext ) ;
 # ifdef DEBUG_EXT printf ( "ext.magic = 0x%x\n" , ext . magic ) ;
 # endif if ( ext . len > end_offset - offset ) {
 error_setg ( errp , "Header extension too large" ) ;
