 bs -> backing_format [ ext . len ] = '\0' ;
 # ifdef DEBUG_EXT printf ( "Qcow2: Got format extension %s\n" , bs -> backing_format ) ;
 # endif break ;
 case QCOW2_EXT_MAGIC_FEATURE_TABLE : if ( p_feature_table != NULL ) {
