static inline int cng_rand ( int * state , int base ) {
 * state = ( * state * 521 + 259 ) & 0xFFFF ;
 return ( * state & 0x7FFF ) * base >> 15 ;
 }

static int64_t qemu_icount_round ( int64_t count ) {
 return ( count + ( 1 << icount_time_shift ) - 1 ) >> icount_time_shift ;
 }

int TSActionDone ( TSAction actionp ) {
 return ( ( Action * ) actionp == ACTION_RESULT_DONE ) ? 1 : 0 ;
 }

int isprint ( int c ) {
 return ( ( c > 31 && c < 127 ) ? 1 : 0 ) ;
 }

static int version_cmp ( const SSL * s , int a , int b ) {
 int dtls = SSL_IS_DTLS ( s ) ;
 if ( a == b ) return 0 ;
 if ( ! dtls ) return a < b ? - 1 : 1 ;
 return DTLS_VERSION_LT ( a , b ) ? - 1 : 1 ;
 }

static int vapic_prepare ( VAPICROMState * s ) {
 vapic_map_rom_writable ( s ) ;
 if ( patch_hypercalls ( s ) < 0 ) {
 return - 1 ;
 }
 vapic_enable_tpr_reporting ( true ) ;
 return 0 ;
 }

static int get_consumed_bytes ( int pos , int buf_size ) {
 if ( pos == 0 ) pos = 1 ;
 if ( pos + 10 > buf_size ) pos = buf_size ;
 return pos ;
 }

static int32_t h264_foc ( int foc ) {
 if ( foc == INT_MAX ) foc = 0 ;
 return foc ;
 }

