void vp9_select_in_frame_q_segment ( VP9_COMP * cpi , int mi_row , int mi_col , int output_enabled , int projected_rate ) {
 VP9_COMMON * const cm = & cpi -> common ;
 const int mi_offset = mi_row * cm -> mi_cols + mi_col ;
 const int bw = num_8x8_blocks_wide_lookup [ BLOCK_64X64 ] ;
 const int bh = num_8x8_blocks_high_lookup [ BLOCK_64X64 ] ;
 const int xmis = MIN ( cm -> mi_cols - mi_col , bw ) ;
 const int ymis = MIN ( cm -> mi_rows - mi_row , bh ) ;
 int complexity_metric = 64 ;
 int x , y ;
 unsigned char segment ;
 if ( ! output_enabled ) {
 segment = 0 ;
 }
 else {
 const int target_rate = ( cpi -> rc . sb64_target_rate * xmis * ymis * 256 ) / ( bw * bh ) ;
 const int aq_strength = get_aq_c_strength ( cm -> base_qindex ) ;
 const int active_segments = aq_c_active_segments [ aq_strength ] ;
 segment = active_segments - 1 ;
 while ( segment > 0 ) {
 if ( projected_rate < ( target_rate * aq_c_transitions [ aq_strength ] [ segment ] ) ) {
 break ;
 }
 -- segment ;
 }
 if ( target_rate > 0 ) {
 complexity_metric = clamp ( ( int ) ( ( projected_rate * 64 ) / target_rate ) , 16 , 255 ) ;
 }
 }
 for ( y = 0 ;
 y < ymis ;
 y ++ ) {
 for ( x = 0 ;
 x < xmis ;
 x ++ ) {
 cpi -> segmentation_map [ mi_offset + y * cm -> mi_cols + x ] = segment ;
 cpi -> complexity_map [ mi_offset + y * cm -> mi_cols + x ] = ( unsigned char ) complexity_metric ;
 }
 }
 }

static int calc_active_worst_quality_one_pass_vbr ( const VP9_COMP * cpi ) {
 const RATE_CONTROL * const rc = & cpi -> rc ;
 const unsigned int curr_frame = cpi -> common . current_video_frame ;
 int active_worst_quality ;
 if ( cpi -> common . frame_type == KEY_FRAME ) {
 active_worst_quality = curr_frame == 0 ? rc -> worst_quality : rc -> last_q [ KEY_FRAME ] * 2 ;
 }
 else {
 if ( ! rc -> is_src_frame_alt_ref && ( cpi -> refresh_golden_frame || cpi -> refresh_alt_ref_frame ) ) {
 active_worst_quality = curr_frame == 1 ? rc -> last_q [ KEY_FRAME ] * 5 / 4 : rc -> last_q [ INTER_FRAME ] ;
 }
 else {
 active_worst_quality = curr_frame == 1 ? rc -> last_q [ KEY_FRAME ] * 2 : rc -> last_q [ INTER_FRAME ] * 2 ;
 }
 }
 return MIN ( active_worst_quality , rc -> worst_quality ) ;
 }

void vp9_update_layer_context_change_config ( VP9_COMP * const cpi , const int target_bandwidth ) {
 SVC * const svc = & cpi -> svc ;
 const VP9EncoderConfig * const oxcf = & cpi -> oxcf ;
 const RATE_CONTROL * const rc = & cpi -> rc ;
