 if ( s -> revision != REV_NVIC ) {
 i += ( GIC_INTERNAL * s -> num_cpu ) ;
 }
 qdev_init_gpio_in ( & s -> busdev . qdev , gic_set_irq , i ) ;
 for ( i = 0 ;
 i < NUM_CPU ( s ) ;
 i ++ ) {
