 }
 memory_region_init_io ( & s -> iomem , OBJECT ( s ) , & gic_dist_ops , s , "gic_dist" , 0x1000 ) ;
 }

static void armv7m_nvic_realize ( DeviceState * dev , Error * * errp ) {
