 s -> gic . num_cpu = 1 ;
 s -> gic . revision = 0xffffffff ;
 s -> num_irq = s -> gic . num_irq ;
 nc -> parent_realize ( dev , errp ) ;
 if ( error_is_set ( errp ) ) {
