static void pxa2xx_fir_rx ( void * opaque , const uint8_t * buf , int size ) {
 PXA2xxFIrState * s = ( PXA2xxFIrState * ) opaque ;
 if ( ! ( s -> control [ 0 ] & ( 1 << 4 ) ) ) return ;
 while ( size -- ) {
 s -> status [ 1 ] |= 1 << 4 ;
 if ( s -> rx_len >= 64 ) {
