 x ++ ) h -> dequant4_coeff [ i ] [ q ] [ ( x >> 2 ) | ( ( x << 2 ) & 0xF ) ] = ( ( uint32_t ) dequant4_coeff_init [ idx ] [ ( x & 1 ) + ( ( x >> 2 ) & 1 ) ] * h -> pps . scaling_matrix4 [ i ] [ x ] ) << shift ;
