static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 KmvcContext * const ctx = avctx -> priv_data ;
 uint8_t * out , * src ;
 int i , ret ;
 int header ;
 int blocksize ;
 const uint8_t * pal = av_packet_get_side_data ( avpkt , AV_PKT_DATA_PALETTE , NULL ) ;
 bytestream2_init ( & ctx -> g , avpkt -> data , avpkt -> size ) ;
 if ( ctx -> pic . data [ 0 ] ) avctx -> release_buffer ( avctx , & ctx -> pic ) ;
 ctx -> pic . reference = 1 ;
 ctx -> pic . buffer_hints = FF_BUFFER_HINTS_VALID ;
 if ( ( ret = ff_get_buffer ( avctx , & ctx -> pic ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 header = bytestream2_get_byte ( & ctx -> g ) ;
 if ( bytestream2_peek_byte ( & ctx -> g ) == 127 ) {
 bytestream2_skip ( & ctx -> g , 3 ) ;
 for ( i = 0 ;
 i < 127 ;
 i ++ ) {
 ctx -> pal [ i + ( header & 0x81 ) ] = bytestream2_get_be24 ( & ctx -> g ) ;
 bytestream2_skip ( & ctx -> g , 1 ) ;
 }
 bytestream2_seek ( & ctx -> g , - 127 * 4 - 3 , SEEK_CUR ) ;
 }
 if ( header & KMVC_KEYFRAME ) {
 ctx -> pic . key_frame = 1 ;
 ctx -> pic . pict_type = AV_PICTURE_TYPE_I ;
 }
 else {
 ctx -> pic . key_frame = 0 ;
 ctx -> pic . pict_type = AV_PICTURE_TYPE_P ;
 }
 if ( header & KMVC_PALETTE ) {
 ctx -> pic . palette_has_changed = 1 ;
 for ( i = 1 ;
 i <= ctx -> palsize ;
 i ++ ) {
 ctx -> pal [ i ] = bytestream2_get_be24 ( & ctx -> g ) ;
 }
 }
 if ( pal ) {
 ctx -> pic . palette_has_changed = 1 ;
 memcpy ( ctx -> pal , pal , AVPALETTE_SIZE ) ;
 }
 if ( ctx -> setpal ) {
 ctx -> setpal = 0 ;
 ctx -> pic . palette_has_changed = 1 ;
 }
 memcpy ( ctx -> pic . data [ 1 ] , ctx -> pal , 1024 ) ;
 blocksize = bytestream2_get_byte ( & ctx -> g ) ;
 if ( blocksize != 8 && blocksize != 127 ) {
 av_log ( avctx , AV_LOG_ERROR , "Block size = %i\n" , blocksize ) ;
 return AVERROR_INVALIDDATA ;
 }
 memset ( ctx -> cur , 0 , 320 * 200 ) ;
 switch ( header & KMVC_METHOD ) {
 case 0 : case 1 : memcpy ( ctx -> cur , ctx -> prev , 320 * 200 ) ;
 break ;
 case 3 : kmvc_decode_intra_8x8 ( ctx , avctx -> width , avctx -> height ) ;
 break ;
 case 4 : kmvc_decode_inter_8x8 ( ctx , avctx -> width , avctx -> height ) ;
 break ;
 default : av_log ( avctx , AV_LOG_ERROR , "Unknown compression method %i\n" , header & KMVC_METHOD ) ;
 return AVERROR_INVALIDDATA ;
 }
 out = ctx -> pic . data [ 0 ] ;
 src = ctx -> cur ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 memcpy ( out , src , avctx -> width ) ;
 src += 320 ;
 out += ctx -> pic . linesize [ 0 ] ;
 }
 if ( ctx -> cur == ctx -> frm0 ) {
 ctx -> cur = ctx -> frm1 ;
 ctx -> prev = ctx -> frm0 ;
 }
 else {
 ctx -> cur = ctx -> frm0 ;
 ctx -> prev = ctx -> frm1 ;
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = ctx -> pic ;
 return avpkt -> size ;
 }

static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * pkt ) {
 BMVDecContext * const c = avctx -> priv_data ;
 int type , scr_off ;
 int i , ret ;
 uint8_t * srcptr , * outptr ;
 c -> stream = pkt -> data ;
 type = bytestream_get_byte ( & c -> stream ) ;
 if ( type & BMV_AUDIO ) {
 int blobs = bytestream_get_byte ( & c -> stream ) ;
 if ( pkt -> size < blobs * 65 + 2 ) {
 av_log ( avctx , AV_LOG_ERROR , "Audio data doesn't fit in frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 c -> stream += blobs * 65 ;
 }
 if ( type & BMV_COMMAND ) {
 int command_size = ( type & BMV_PRINT ) ? 8 : 10 ;
 if ( c -> stream - pkt -> data + command_size > pkt -> size ) {
 av_log ( avctx , AV_LOG_ERROR , "Command data doesn't fit in frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 c -> stream += command_size ;
 }
 if ( type & BMV_PALETTE ) {
 if ( c -> stream - pkt -> data > pkt -> size - 768 ) {
 av_log ( avctx , AV_LOG_ERROR , "Palette data doesn't fit in frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 for ( i = 0 ;
 i < 256 ;
 i ++ ) c -> pal [ i ] = bytestream_get_be24 ( & c -> stream ) ;
 }
 if ( type & BMV_SCROLL ) {
 if ( c -> stream - pkt -> data > pkt -> size - 2 ) {
 av_log ( avctx , AV_LOG_ERROR , "Screen offset data doesn't fit in frame\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 scr_off = ( int16_t ) bytestream_get_le16 ( & c -> stream ) ;
 }
 else if ( ( type & BMV_INTRA ) == BMV_INTRA ) {
 scr_off = - 640 ;
 }
 else {
 scr_off = 0 ;
 }
 if ( c -> pic . data [ 0 ] ) avctx -> release_buffer ( avctx , & c -> pic ) ;
 c -> pic . reference = 3 ;
 if ( ( ret = ff_get_buffer ( avctx , & c -> pic ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 if ( decode_bmv_frame ( c -> stream , pkt -> size - ( c -> stream - pkt -> data ) , c -> frame , scr_off ) ) {
 av_log ( avctx , AV_LOG_ERROR , "Error decoding frame data\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 memcpy ( c -> pic . data [ 1 ] , c -> pal , AVPALETTE_SIZE ) ;
 c -> pic . palette_has_changed = type & BMV_PALETTE ;
 outptr = c -> pic . data [ 0 ] ;
 srcptr = c -> frame ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 memcpy ( outptr , srcptr , avctx -> width ) ;
 srcptr += avctx -> width ;
 outptr += c -> pic . linesize [ 0 ] ;
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = c -> pic ;
 return pkt -> size ;
 }

