 y < 4 ;
 y ++ ) for ( x = 0 ;
 x < 4 ;
 x ++ , pattern >>= 1 ) cur [ x + y * width ] = ( pattern & 1 ) ? b : a ;
 break ;
 case 1 : pattern = ~ pattern ;
 case 2 : a = bytestream2_get_byte ( & g ) ;
