 y < 4 ;
 y ++ ) for ( x = 0 ;
 x < 4 ;
 x ++ , pattern >>= 1 ) if ( pattern & 1 && check_pixel ( prev + x + y * width , pstart , pend ) ) cur [ x + y * width ] = prev [ x + y * width ] ;
