 return FALSE ;
 }
 demux -> state = GST_ASF_DEMUX_STATE_DATA ;
 if ( ! demux -> broadcast && obj . size > 50 ) {
 demux -> data_size = obj . size - 50 ;
 demux -> index_offset = demux -> data_offset + demux -> data_size ;
 }
 else {
 demux -> data_size = 0 ;
 demux -> index_offset = 0 ;
 }
 demux -> packet = 0 ;
 if ( ! demux -> broadcast ) {
