static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 JvContext * s = avctx -> priv_data ;
 int buf_size = avpkt -> size ;
 const uint8_t * buf = avpkt -> data ;
 const uint8_t * buf_end = buf + buf_size ;
 int video_size , video_type , i , j , ret ;
 video_size = AV_RL32 ( buf ) ;
 video_type = buf [ 4 ] ;
 buf += 5 ;
 if ( video_size ) {
 if ( ( ret = ff_reget_buffer ( avctx , & s -> frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 if ( video_type == 0 || video_type == 1 ) {
 GetBitContext gb ;
 init_get_bits ( & gb , buf , 8 * FFMIN ( video_size , buf_end - buf ) ) ;
 for ( j = 0 ;
 j < avctx -> height ;
 j += 8 ) for ( i = 0 ;
 i < avctx -> width ;
 i += 8 ) decode8x8 ( & gb , s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] + i , s -> frame . linesize [ 0 ] , & s -> dsp ) ;
 buf += video_size ;
 }
 else if ( video_type == 2 ) {
 if ( buf + 1 <= buf_end ) {
 int v = * buf ++ ;
 for ( j = 0 ;
 j < avctx -> height ;
 j ++ ) memset ( s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] , v , avctx -> width ) ;
 }
 }
 else {
 av_log ( avctx , AV_LOG_WARNING , "unsupported frame type %i\n" , video_type ) ;
 return AVERROR_INVALIDDATA ;
 }
 }
 if ( buf < buf_end ) {
 for ( i = 0 ;
 i < AVPALETTE_COUNT && buf + 3 <= buf_end ;
 i ++ ) {
 s -> palette [ i ] = AV_RB24 ( buf ) << 2 ;
 buf += 3 ;
 }
 s -> palette_has_changed = 1 ;
 }
 if ( video_size ) {
 s -> frame . key_frame = 1 ;
 s -> frame . pict_type = AV_PICTURE_TYPE_I ;
 s -> frame . palette_has_changed = s -> palette_has_changed ;
 s -> palette_has_changed = 0 ;
 memcpy ( s -> frame . data [ 1 ] , s -> palette , AVPALETTE_SIZE ) ;
 if ( ( ret = av_frame_ref ( data , & s -> frame ) ) < 0 ) return ret ;
 * got_frame = 1 ;
 }
 return buf_size ;
 }

static inline int copy_block ( AVCodecContext * avctx , uint8_t * to , uint8_t * from , int offset , int height , int stride ) {
 int i ;
 int width = height ;
 int from_x = offset % WIDTH ;
 int from_y = offset / WIDTH ;
 int overflow = from_x + width - WIDTH ;
 if ( ! from ) {
 return 0 ;
 }
 if ( from_y + height > HEIGHT ) {
 av_log ( avctx , AV_LOG_ERROR , "invalid offset %d during C93 decoding\n" , offset ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( overflow > 0 ) {
 width -= overflow ;
 for ( i = 0 ;
 i < height ;
 i ++ ) {
 memcpy ( & to [ i * stride + width ] , & from [ ( from_y + i ) * stride ] , overflow ) ;
 }
 }
 for ( i = 0 ;
 i < height ;
 i ++ ) {
 memcpy ( & to [ i * stride ] , & from [ ( from_y + i ) * stride + from_x ] , width ) ;
 }
 return 0 ;
 }

static void show_string ( fz_context * ctx , pdf_run_processor * pr , unsigned char * buf , int len ) {
 pdf_gstate * gstate = pr -> gstate + pr -> gtop ;
 pdf_font_desc * fontdesc = gstate -> text . font ;
 unsigned char * end = buf + len ;
 unsigned int cpt ;
 int cid ;
 while ( buf < end ) {
 int w = pdf_decode_cmap ( fontdesc -> encoding , buf , end , & cpt ) ;
 buf += w ;
 cid = pdf_lookup_cmap ( fontdesc -> encoding , cpt ) ;
 if ( cid >= 0 ) pdf_show_char ( ctx , pr , cid ) ;
 else fz_warn ( ctx , "cannot encode character" ) ;
 if ( cpt == 32 && w == 1 ) pdf_show_space ( ctx , pr , gstate -> text . word_space ) ;
 }
 }

