static inline int base_key_length ( const cipher_type_t * cipher , int key_length ) {
 switch ( cipher -> id ) {
 case AES_128_ICM : case AES_192_ICM : case AES_256_ICM : return key_length - 14 ;
 break ;
 case AES_128_GCM : return 16 ;
 break ;
 case AES_256_GCM : return 32 ;
 break ;
 default : return key_length ;
 break ;
 }
 }

static int selinux_kernel_read_file ( struct file * file , enum kernel_read_file_id id ) {
 int rc = 0 ;
 switch ( id ) {
 case READING_MODULE : rc = selinux_kernel_module_from_file ( file ) ;
 break ;
 default : break ;
 }
 return rc ;
 }

static const char * virLogPriorityString ( virLogPriority lvl ) {
 switch ( lvl ) {
 case VIR_LOG_DEBUG : return "debug" ;
 case VIR_LOG_INFO : return "info" ;
 case VIR_LOG_WARN : return "warning" ;
 case VIR_LOG_ERROR : return "error" ;
 }
 return "unknown" ;
 }

