 i ++ ) {
 if ( from -> key_data_length [ i ] ) {
 to -> key_data_contents [ i ] = malloc ( from -> key_data_length [ i ] ) ;
 if ( to -> key_data_contents [ i ] == NULL ) {
 for ( i = 0 ;
