static void sbr_make_f_tablelim ( SpectralBandReplication * sbr ) {
 int k ;
 if ( sbr -> bs_limiter_bands > 0 ) {
 static const float bands_warped [ 3 ] = {
 1.32715174233856803909f , 1.18509277094158210129f , 1.11987160404675912501f }
 ;
 const float lim_bands_per_octave_warped = bands_warped [ sbr -> bs_limiter_bands - 1 ] ;
 int16_t patch_borders [ 7 ] ;
 uint16_t * in = sbr -> f_tablelim + 1 , * out = sbr -> f_tablelim ;
 patch_borders [ 0 ] = sbr -> kx [ 1 ] ;
 for ( k = 1 ;
 k <= sbr -> num_patches ;
 k ++ ) patch_borders [ k ] = patch_borders [ k - 1 ] + sbr -> patch_num_subbands [ k - 1 ] ;
 memcpy ( sbr -> f_tablelim , sbr -> f_tablelow , ( sbr -> n [ 0 ] + 1 ) * sizeof ( sbr -> f_tablelow [ 0 ] ) ) ;
 if ( sbr -> num_patches > 1 ) memcpy ( sbr -> f_tablelim + sbr -> n [ 0 ] + 1 , patch_borders + 1 , ( sbr -> num_patches - 1 ) * sizeof ( patch_borders [ 0 ] ) ) ;
 qsort ( sbr -> f_tablelim , sbr -> num_patches + sbr -> n [ 0 ] , sizeof ( sbr -> f_tablelim [ 0 ] ) , qsort_comparison_function_int16 ) ;
 sbr -> n_lim = sbr -> n [ 0 ] + sbr -> num_patches - 1 ;
 while ( out < sbr -> f_tablelim + sbr -> n_lim ) {
 if ( * in >= * out * lim_bands_per_octave_warped ) {
 * ++ out = * in ++ ;
 }
 else if ( * in == * out || ! in_table_int16 ( patch_borders , sbr -> num_patches , * in ) ) {
 in ++ ;
 sbr -> n_lim -- ;
 }
 else if ( ! in_table_int16 ( patch_borders , sbr -> num_patches , * out ) ) {
 * out = * in ++ ;
 sbr -> n_lim -- ;
 }
 else {
 * ++ out = * in ++ ;
 }
 }
 }
 else {
 sbr -> f_tablelim [ 0 ] = sbr -> f_tablelow [ 0 ] ;
 sbr -> f_tablelim [ 1 ] = sbr -> f_tablelow [ sbr -> n [ 0 ] ] ;
 sbr -> n_lim = 1 ;
 }
 }

static int lag_decode_zero_run_line ( LagarithContext * l , uint8_t * dst , const uint8_t * src , const uint8_t * src_end , int width , int esc_count ) {
 int i = 0 ;
 int count ;
 uint8_t zero_run = 0 ;
 const uint8_t * src_start = src ;
 uint8_t mask1 = - ( esc_count < 2 ) ;
 uint8_t mask2 = - ( esc_count < 3 ) ;
 uint8_t * end = dst + ( width - 2 ) ;
 output_zeros : if ( l -> zeros_rem ) {
 count = FFMIN ( l -> zeros_rem , width - i ) ;
 if ( end - dst < count ) {
 av_log ( l -> avctx , AV_LOG_ERROR , "Too many zeros remaining.\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 memset ( dst , 0 , count ) ;
 l -> zeros_rem -= count ;
 dst += count ;
 }
 while ( dst < end ) {
 i = 0 ;
 while ( ! zero_run && dst + i < end ) {
 i ++ ;
 if ( src + i >= src_end ) return AVERROR_INVALIDDATA ;
 zero_run = ! ( src [ i ] | ( src [ i + 1 ] & mask1 ) | ( src [ i + 2 ] & mask2 ) ) ;
 }
 if ( zero_run ) {
 zero_run = 0 ;
 i += esc_count ;
 memcpy ( dst , src , i ) ;
 dst += i ;
 l -> zeros_rem = lag_calc_zero_run ( src [ i ] ) ;
 src += i + 1 ;
 goto output_zeros ;
 }
 else {
 memcpy ( dst , src , i ) ;
 src += i ;
 dst += i ;
 }
 }
 return src_start - src ;
 }

static void apply_pitch_filters ( QCELPContext * q , float * cdn_vector ) {
 int i ;
 const float * v_synthesis_filtered , * v_pre_filtered ;
 if ( q -> bitrate >= RATE_HALF || q -> bitrate == SILENCE || ( q -> bitrate == I_F_Q && ( q -> prev_bitrate >= RATE_HALF ) ) ) {
 if ( q -> bitrate >= RATE_HALF ) {
 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 q -> pitch_gain [ i ] = q -> frame . plag [ i ] ? ( q -> frame . pgain [ i ] + 1 ) * 0.25 : 0.0 ;
 q -> pitch_lag [ i ] = q -> frame . plag [ i ] + 16 ;
 }
 }
 else {
 float max_pitch_gain ;
 if ( q -> bitrate == I_F_Q ) {
 if ( q -> erasure_count < 3 ) max_pitch_gain = 0.9 - 0.3 * ( q -> erasure_count - 1 ) ;
 else max_pitch_gain = 0.0 ;
 }
