static void file_change_cr ( const char * s , struct branch * b , int rename ) {
 const char * d ;
 static struct strbuf s_uq = STRBUF_INIT ;
 static struct strbuf d_uq = STRBUF_INIT ;
 const char * endp ;
 struct tree_entry leaf ;
 strbuf_reset ( & s_uq ) ;
 if ( ! unquote_c_style ( & s_uq , s , & endp ) ) {
 if ( * endp != ' ' ) die ( "Missing space after source: %s" , command_buf . buf ) ;
 }
 else {
 endp = strchr ( s , ' ' ) ;
 if ( ! endp ) die ( "Missing space after source: %s" , command_buf . buf ) ;
 strbuf_add ( & s_uq , s , endp - s ) ;
 }
 s = s_uq . buf ;
 endp ++ ;
 if ( ! * endp ) die ( "Missing dest: %s" , command_buf . buf ) ;
 d = endp ;
 strbuf_reset ( & d_uq ) ;
 if ( ! unquote_c_style ( & d_uq , d , & endp ) ) {
 if ( * endp ) die ( "Garbage after dest in: %s" , command_buf . buf ) ;
 d = d_uq . buf ;
 }
 memset ( & leaf , 0 , sizeof ( leaf ) ) ;
 if ( rename ) tree_content_remove ( & b -> branch_tree , s , & leaf , 1 ) ;
 else tree_content_get ( & b -> branch_tree , s , & leaf , 1 ) ;
 if ( ! leaf . versions [ 1 ] . mode ) die ( "Path %s not in branch" , s ) ;
 if ( ! * d ) {
 tree_content_replace ( & b -> branch_tree , leaf . versions [ 1 ] . sha1 , leaf . versions [ 1 ] . mode , leaf . tree ) ;
 return ;
 }
 tree_content_set ( & b -> branch_tree , d , leaf . versions [ 1 ] . sha1 , leaf . versions [ 1 ] . mode , leaf . tree ) ;
 }

static void rice_decompress ( ALACContext * alac , int32_t * output_buffer , int nb_samples , int bps , int rice_history_mult ) {
 int i ;
 unsigned int history = alac -> rice_initial_history ;
 int sign_modifier = 0 ;
 for ( i = 0 ;
 i < nb_samples ;
 i ++ ) {
 int k ;
 unsigned int x ;
 k = av_log2 ( ( history >> 9 ) + 3 ) ;
 k = FFMIN ( k , alac -> rice_limit ) ;
 x = decode_scalar ( & alac -> gb , k , bps ) ;
 x += sign_modifier ;
 sign_modifier = 0 ;
 output_buffer [ i ] = ( x >> 1 ) ^ - ( x & 1 ) ;
 if ( x > 0xffff ) history = 0xffff ;
 else history += x * rice_history_mult - ( ( history * rice_history_mult ) >> 9 ) ;
 if ( ( history < 128 ) && ( i + 1 < nb_samples ) ) {
 int block_size ;
 k = 7 - av_log2 ( history ) + ( ( history + 16 ) >> 6 ) ;
 k = FFMIN ( k , alac -> rice_limit ) ;
 block_size = decode_scalar ( & alac -> gb , k , 16 ) ;
 if ( block_size > 0 ) {
 if ( block_size >= nb_samples - i ) {
 av_log ( alac -> avctx , AV_LOG_ERROR , "invalid zero block size of %d %d %d\n" , block_size , nb_samples , i ) ;
 block_size = nb_samples - i - 1 ;
 }
 memset ( & output_buffer [ i + 1 ] , 0 , block_size * sizeof ( * output_buffer ) ) ;
 i += block_size ;
 }
 if ( block_size <= 0xffff ) sign_modifier = 1 ;
 history = 0 ;
 }
 }
 }

