 if ( vpx_codec_decode ( & decoder , buf , ( unsigned int ) bytes_in_buffer , NULL , 0 ) ) {
 const char * detail = vpx_codec_error_detail ( & decoder ) ;
 warn ( "Failed to decode frame %d: %s" , frame_in , vpx_codec_error ( & decoder ) ) ;
 if ( detail ) warn ( "Additional information: %s" , detail ) ;
 if ( ! keep_going ) goto fail ;
 }
 vpx_usec_timer_mark ( & timer ) ;
 dx_time += vpx_usec_timer_elapsed ( & timer ) ;
 }
 }
 vpx_usec_timer_start ( & timer ) ;
 got_data = 0 ;
 if ( ( img = vpx_codec_get_frame ( & decoder , & iter ) ) ) {
 ++ frame_out ;
 got_data = 1 ;
 }
 vpx_usec_timer_mark ( & timer ) ;
 dx_time += ( unsigned int ) vpx_usec_timer_elapsed ( & timer ) ;
 if ( vpx_codec_control ( & decoder , VP8D_GET_FRAME_CORRUPTED , & corrupted ) ) {
 warn ( "Failed VP8_GET_FRAME_CORRUPTED: %s" , vpx_codec_error ( & decoder ) ) ;
 goto fail ;
 }
 frames_corrupted += corrupted ;
 if ( progress ) show_progress ( frame_in , frame_out , dx_time ) ;
 if ( ! noblit && img ) {
 const int PLANES_YUV [ ] = {
 VPX_PLANE_Y , VPX_PLANE_U , VPX_PLANE_V }
 ;
 const int PLANES_YVU [ ] = {
 VPX_PLANE_Y , VPX_PLANE_V , VPX_PLANE_U }
 ;
 const int * planes = flipuv ? PLANES_YVU : PLANES_YUV ;
 if ( do_scale ) {
 if ( frame_out == 1 ) {
 int display_width = vpx_input_ctx . width ;
 int display_height = vpx_input_ctx . height ;
 if ( ! display_width || ! display_height ) {
 int display_size [ 2 ] ;
 if ( vpx_codec_control ( & decoder , VP9D_GET_DISPLAY_SIZE , display_size ) ) {
 display_width = img -> d_w ;
 display_height = img -> d_h ;
 }
 else {
 display_width = display_size [ 0 ] ;
 display_height = display_size [ 1 ] ;
 }
 }
 scaled_img = vpx_img_alloc ( NULL , img -> fmt , display_width , display_height , 16 ) ;
 scaled_img -> bit_depth = img -> bit_depth ;
 }
 if ( img -> d_w != scaled_img -> d_w || img -> d_h != scaled_img -> d_h ) {
 # if CONFIG_LIBYUV vpx_image_scale ( img , scaled_img , kFilterBox ) ;
 img = scaled_img ;
 # else fprintf ( stderr , "Failed to scale output frame: %s.\n" "Scaling is disabled in this configuration. " "To enable scaling, configure with --enable-libyuv\n" , vpx_codec_error ( & decoder ) ) ;
 return EXIT_FAILURE ;
 # endif }
 }
 # if CONFIG_VP9 && CONFIG_VP9_HIGHBITDEPTH if ( ! output_bit_depth ) {
 output_bit_depth = img -> bit_depth ;
 }
 if ( output_bit_depth != img -> bit_depth ) {
 if ( ! img_shifted ) {
 if ( output_bit_depth == 8 ) {
 img_shifted = vpx_img_alloc ( NULL , img -> fmt - VPX_IMG_FMT_HIGHBITDEPTH , img -> d_w , img -> d_h , 16 ) ;
 }
 else {
 img_shifted = vpx_img_alloc ( NULL , img -> fmt | VPX_IMG_FMT_HIGHBITDEPTH , img -> d_w , img -> d_h , 16 ) ;
 }
 img_shifted -> bit_depth = output_bit_depth ;
 }
 if ( output_bit_depth > img -> bit_depth ) {
 img_upshift ( img_shifted , img , output_bit_depth - img -> bit_depth ) ;
 }
 else {
 img_downshift ( img_shifted , img , img -> bit_depth - output_bit_depth ) ;
 }
 img = img_shifted ;
 }
 # endif if ( single_file ) {
 if ( use_y4m ) {
 char buf [ Y4M_BUFFER_SIZE ] = {
 0 }
 ;
 size_t len = 0 ;
 if ( frame_out == 1 ) {
 len = y4m_write_file_header ( buf , sizeof ( buf ) , vpx_input_ctx . width , vpx_input_ctx . height , & vpx_input_ctx . framerate , img -> fmt , img -> bit_depth ) ;
 if ( do_md5 ) {
 MD5Update ( & md5_ctx , ( md5byte * ) buf , ( unsigned int ) len ) ;
 }
 else {
 fputs ( buf , outfile ) ;
 }
 }
 len = y4m_write_frame_header ( buf , sizeof ( buf ) ) ;
 if ( do_md5 ) {
 MD5Update ( & md5_ctx , ( md5byte * ) buf , ( unsigned int ) len ) ;
 }
 else {
 fputs ( buf , outfile ) ;
 }
 }
 else {
 if ( frame_out == 1 ) {
 if ( opt_i420 ) {
 if ( img -> fmt != VPX_IMG_FMT_I420 && img -> fmt != VPX_IMG_FMT_I42016 ) {
 fprintf ( stderr , "Cannot produce i420 output for bit-stream.\n" ) ;
 goto fail ;
 }
 }
 if ( opt_yv12 ) {
 if ( ( img -> fmt != VPX_IMG_FMT_I420 && img -> fmt != VPX_IMG_FMT_YV12 ) || img -> bit_depth != 8 ) {
 fprintf ( stderr , "Cannot produce yv12 output for bit-stream.\n" ) ;
 goto fail ;
 }
 }
 }
 }
 if ( do_md5 ) {
 update_image_md5 ( img , planes , & md5_ctx ) ;
 }
 else {
 write_image_file ( img , planes , outfile ) ;
 }
 }
 else {
 generate_filename ( outfile_pattern , outfile_name , PATH_MAX , img -> d_w , img -> d_h , frame_in ) ;
 if ( do_md5 ) {
 MD5Init ( & md5_ctx ) ;
 update_image_md5 ( img , planes , & md5_ctx ) ;
 MD5Final ( md5_digest , & md5_ctx ) ;
 print_md5 ( md5_digest , outfile_name ) ;
 }
 else {
 outfile = open_outfile ( outfile_name ) ;
 write_image_file ( img , planes , outfile ) ;
 fclose ( outfile ) ;
 }
 }
 }
 if ( stop_after && frame_in >= stop_after ) break ;
 }
 if ( summary || progress ) {
 show_progress ( frame_in , frame_out , dx_time ) ;
 fprintf ( stderr , "\n" ) ;
 }
 if ( frames_corrupted ) fprintf ( stderr , "WARNING: %d frames corrupted.\n" , frames_corrupted ) ;
 fail : if ( vpx_codec_destroy ( & decoder ) ) {
 fprintf ( stderr , "Failed to destroy decoder: %s\n" , vpx_codec_error ( & decoder ) ) ;
 return EXIT_FAILURE ;
 }
 if ( ! noblit && single_file ) {
 if ( do_md5 ) {
 MD5Final ( md5_digest , & md5_ctx ) ;
 print_md5 ( md5_digest , outfile_name ) ;
 }
 else {
 fclose ( outfile ) ;
 }
 }
 # if CONFIG_WEBM_IO if ( input . vpx_input_ctx -> file_type == FILE_TYPE_WEBM ) webm_free ( input . webm_ctx ) ;
 # endif if ( input . vpx_input_ctx -> file_type != FILE_TYPE_WEBM ) free ( buf ) ;
 if ( scaled_img ) vpx_img_free ( scaled_img ) ;
 # if CONFIG_VP9 && CONFIG_VP9_HIGHBITDEPTH if ( img_shifted ) vpx_img_free ( img_shifted ) ;
 # endif for ( i = 0 ;
 i < ext_fb_list . num_external_frame_buffers ;
 ++ i ) {
 free ( ext_fb_list . ext_fb [ i ] . data ) ;
 }
 free ( ext_fb_list . ext_fb ) ;
 fclose ( infile ) ;
 free ( argv ) ;
 return frames_corrupted ? EXIT_FAILURE : EXIT_SUCCESS ;
 }

void pk_transaction_cancel_bg ( PkTransaction * transaction ) {
 g_debug ( "CancelBg method called on %s" , transaction -> priv -> tid ) ;
 if ( transaction -> priv -> state == PK_TRANSACTION_STATE_FINISHED ) return ;
 if ( ! pk_backend_is_implemented ( transaction -> priv -> backend , PK_ROLE_ENUM_CANCEL ) ) {
 g_warning ( "Cancel not supported by backend" ) ;
 return ;
 }
 if ( transaction -> priv -> state <= PK_TRANSACTION_STATE_READY ) {
 pk_transaction_finished_emit ( transaction , PK_EXIT_ENUM_CANCELLED , 0 ) ;
 return ;
 }
 pk_backend_job_set_status ( transaction -> priv -> job , PK_STATUS_ENUM_CANCEL ) ;
 pk_backend_job_set_allow_cancel ( transaction -> priv -> job , FALSE ) ;
 pk_backend_job_set_exit_code ( transaction -> priv -> job , PK_EXIT_ENUM_CANCELLED_PRIORITY ) ;
 pk_backend_cancel ( transaction -> priv -> backend , transaction -> priv -> job ) ;
 }

static void sig_complete_topic ( GList * * list , WINDOW_REC * window , const char * word , const char * line , int * want_space ) {
 const char * topic ;
 g_return_if_fail ( list != NULL ) ;
 g_return_if_fail ( word != NULL ) ;
 if ( * word == '\0' && IS_CHANNEL ( window -> active ) ) {
 topic = CHANNEL ( window -> active ) -> topic ;
 if ( topic != NULL ) {
 * list = g_list_append ( NULL , g_strdup ( topic ) ) ;
 signal_stop ( ) ;
 }
 }
 }

static void sig_complete_alias ( GList * * list , WINDOW_REC * window , const char * word , const char * line , int * want_space ) {
 const char * definition ;
 g_return_if_fail ( list != NULL ) ;
 g_return_if_fail ( word != NULL ) ;
 g_return_if_fail ( line != NULL ) ;
 if ( * line != '\0' ) {
 if ( ( definition = alias_find ( line ) ) != NULL ) {
 * list = g_list_append ( NULL , g_strdup ( definition ) ) ;
 signal_stop ( ) ;
 }
 }
 else {
 * list = completion_get_aliases ( word ) ;
 if ( * list != NULL ) signal_stop ( ) ;
 }
 }

static gboolean pk_transaction_set_hint ( PkTransaction * transaction , const gchar * key , const gchar * value , GError * * error ) {
 PkTransactionPrivate * priv = transaction -> priv ;
 if ( g_strcmp0 ( key , "locale" ) == 0 ) {
 pk_backend_job_set_locale ( priv -> job , value ) ;
 return TRUE ;
 }
 if ( g_strcmp0 ( key , "frontend-socket" ) == 0 ) {
 if ( value == NULL || value [ 0 ] == '\0' ) {
 g_set_error_literal ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "Could not set frontend-socket to nothing" ) ;
 return FALSE ;
 }
 if ( value [ 0 ] != '/' ) {
 g_set_error_literal ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "frontend-socket has to be an absolute path" ) ;
 return FALSE ;
 }
 if ( ! g_file_test ( value , G_FILE_TEST_EXISTS ) ) {
 g_set_error_literal ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "frontend-socket does not exist" ) ;
 return FALSE ;
 }
 pk_backend_job_set_frontend_socket ( priv -> job , value ) ;
 return TRUE ;
 }
 if ( g_strcmp0 ( key , "background" ) == 0 ) {
 if ( g_strcmp0 ( value , "true" ) == 0 ) {
 pk_backend_job_set_background ( priv -> job , TRUE ) ;
 }
 else if ( g_strcmp0 ( value , "false" ) == 0 ) {
 pk_backend_job_set_background ( priv -> job , FALSE ) ;
 }
 else {
 g_set_error ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "background hint expects true or false, not %s" , value ) ;
 return FALSE ;
 }
 return TRUE ;
 }
 if ( g_strcmp0 ( key , "interactive" ) == 0 ) {
 if ( g_strcmp0 ( value , "true" ) == 0 ) {
 pk_backend_job_set_interactive ( priv -> job , TRUE ) ;
 }
 else if ( g_strcmp0 ( value , "false" ) == 0 ) {
 pk_backend_job_set_interactive ( priv -> job , FALSE ) ;
 }
 else {
 g_set_error ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "interactive hint expects true or false, not %s" , value ) ;
 return FALSE ;
 }
 return TRUE ;
 }
 if ( g_strcmp0 ( key , "cache-age" ) == 0 ) {
 guint cache_age ;
 if ( ! pk_strtouint ( value , & cache_age ) ) {
 g_set_error ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "cannot parse cache age value %s" , value ) ;
 return FALSE ;
 }
 if ( cache_age == 0 ) {
 g_set_error_literal ( error , PK_TRANSACTION_ERROR , PK_TRANSACTION_ERROR_NOT_SUPPORTED , "cannot set a cache age of zero" ) ;
 return FALSE ;
 }
 pk_backend_job_set_cache_age ( priv -> job , cache_age ) ;
 return TRUE ;
 }
 g_warning ( "unknown option: %s with value %s" , key , value ) ;
 return TRUE ;
 }

static void pdf_set_color ( fz_context * ctx , pdf_run_processor * pr , int what , float * v ) {
 pdf_gstate * gstate = pr -> gstate + pr -> gtop ;
 pdf_material * mat ;
 gstate = pdf_flush_text ( ctx , pr ) ;
 mat = what == PDF_FILL ? & gstate -> fill : & gstate -> stroke ;
 switch ( mat -> kind ) {
 case PDF_MAT_PATTERN : case PDF_MAT_COLOR : fz_clamp_color ( ctx , mat -> colorspace , v , mat -> v ) ;
 break ;
 default : fz_warn ( ctx , "color incompatible with material" ) ;
 }
 mat -> gstate_num = pr -> gparent ;
 }

static void pdf_set_colorspace ( fz_context * ctx , pdf_run_processor * pr , int what , fz_colorspace * colorspace ) {
 pdf_gstate * gstate = pr -> gstate + pr -> gtop ;
 pdf_material * mat ;
 int n = fz_colorspace_n ( ctx , colorspace ) ;
 gstate = pdf_flush_text ( ctx , pr ) ;
 mat = what == PDF_FILL ? & gstate -> fill : & gstate -> stroke ;
 fz_drop_colorspace ( ctx , mat -> colorspace ) ;
 mat -> kind = PDF_MAT_COLOR ;
 mat -> colorspace = fz_keep_colorspace ( ctx , colorspace ) ;
 mat -> v [ 0 ] = 0 ;
 mat -> v [ 1 ] = 0 ;
 mat -> v [ 2 ] = 0 ;
 mat -> v [ 3 ] = 1 ;
 if ( pdf_is_tint_colorspace ( ctx , colorspace ) ) {
 int i ;
 for ( i = 0 ;
 i < n ;
 i ++ ) mat -> v [ i ] = 1.0f ;
 }
 }

static void pdf_set_shade ( fz_context * ctx , pdf_run_processor * pr , int what , fz_shade * shade ) {
 pdf_gstate * gs ;
 pdf_material * mat ;
 gs = pdf_flush_text ( ctx , pr ) ;
 mat = what == PDF_FILL ? & gs -> fill : & gs -> stroke ;
 fz_drop_shade ( ctx , mat -> shade ) ;
 mat -> kind = PDF_MAT_SHADE ;
 mat -> shade = fz_keep_shade ( ctx , shade ) ;
 mat -> gstate_num = pr -> gparent ;
 }

static void pick_quickcompress_mode ( vpx_codec_alg_priv_t * ctx , unsigned long duration , unsigned long deadline ) {
 MODE new_mode = BEST ;
 switch ( ctx -> cfg . g_pass ) {
 case VPX_RC_ONE_PASS : if ( deadline > 0 ) {
 const vpx_codec_enc_cfg_t * const cfg = & ctx -> cfg ;
 const uint64_t duration_us = ( uint64_t ) duration * 1000000 * ( uint64_t ) cfg -> g_timebase . num / ( uint64_t ) cfg -> g_timebase . den ;
 new_mode = ( deadline > duration_us ) ? GOOD : REALTIME ;
 }
 else {
 new_mode = BEST ;
 }
 break ;
 case VPX_RC_FIRST_PASS : break ;
 case VPX_RC_LAST_PASS : new_mode = deadline > 0 ? GOOD : BEST ;
 break ;
 }
 if ( ctx -> oxcf . mode != new_mode ) {
 ctx -> oxcf . mode = new_mode ;
 vp9_change_config ( ctx -> cpi , & ctx -> oxcf ) ;
 }
 }

