 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 q -> pitch_gain [ i ] = q -> frame . plag [ i ] ? ( q -> frame . pgain [ i ] + 1 ) * 0.25 : 0.0 ;
 q -> pitch_lag [ i ] = q -> frame . plag [ i ] + 16 ;
 }
 }
 else {
