 if ( ! top_loc [ i ] || ! top_loc [ i ] -> quant_idx ) break ;
 args = top_loc [ i ] ;
 prev_bytes = args -> bytes ;
 new_idx = FFMAX ( args -> quant_idx - 1 , 0 ) ;
 bits = count_hq_slice ( args , new_idx ) ;
 bytes = SSIZE_ROUND ( bits >> 3 ) ;
 diff = bytes - prev_bytes ;
 if ( ( bytes_left - diff ) > 0 ) {
