static struct tree_content * dup_tree_content ( struct tree_content * s ) {
 struct tree_content * d ;
 struct tree_entry * a , * b ;
 unsigned int i ;
 if ( ! s ) return NULL ;
 d = new_tree_content ( s -> entry_count ) ;
 for ( i = 0 ;
 i < s -> entry_count ;
 i ++ ) {
 a = s -> entries [ i ] ;
 b = new_tree_entry ( ) ;
 memcpy ( b , a , sizeof ( * a ) ) ;
 if ( a -> tree && is_null_sha1 ( b -> versions [ 1 ] . sha1 ) ) b -> tree = dup_tree_content ( a -> tree ) ;
 else b -> tree = NULL ;
 d -> entries [ i ] = b ;
 }
 d -> entry_count = s -> entry_count ;
 d -> delta_depth = s -> delta_depth ;
 return d ;
 }

static int is_response_status_relevant ( modsec_rec * msr , int status ) {
 char * my_error_msg = NULL ;
 apr_status_t rc ;
 char buf [ 32 ] ;
 if ( ( msr -> txcfg -> auditlog_relevant_regex == NULL ) || ( msr -> txcfg -> auditlog_relevant_regex == NOT_SET_P ) ) {
 return 0 ;
 }
 apr_snprintf ( buf , sizeof ( buf ) , "%d" , status ) ;
 rc = msc_regexec ( msr -> txcfg -> auditlog_relevant_regex , buf , strlen ( buf ) , & my_error_msg ) ;
 if ( rc >= 0 ) return 1 ;
 if ( rc == PCRE_ERROR_NOMATCH ) return 0 ;
 msr_log ( msr , 1 , "Regex processing failed (rc %d): %s" , rc , my_error_msg ) ;
 return 0 ;
 }

static int kq_insert ( struct kqop * kqop , struct kevent * kev ) {
 int nevents = kqop -> nevents ;
 if ( kqop -> nchanges == nevents ) {
 struct kevent * newchange ;
 struct kevent * newresult ;
 nevents *= 2 ;
 newchange = realloc ( kqop -> changes , nevents * sizeof ( struct kevent ) ) ;
 if ( newchange == NULL ) {
 event_warn ( "%s: malloc" , __func__ ) ;
 return ( - 1 ) ;
 }
 kqop -> changes = newchange ;
 newresult = realloc ( kqop -> events , nevents * sizeof ( struct kevent ) ) ;
 if ( newresult == NULL ) {
 event_warn ( "%s: malloc" , __func__ ) ;
 return ( - 1 ) ;
 }
 kqop -> events = newresult ;
 kqop -> nevents = nevents ;
 }
 memcpy ( & kqop -> changes [ kqop -> nchanges ++ ] , kev , sizeof ( struct kevent ) ) ;
 event_debug ( ( "%s: fd %d %s%s" , __func__ , ( int ) kev -> ident , kev -> filter == EVFILT_READ ? "EVFILT_READ" : "EVFILT_WRITE" , kev -> flags == EV_DELETE ? " (del)" : "" ) ) ;
 return ( 0 ) ;
 }

static void multiple_read_cb ( int fd , short event , void * arg ) {
 struct event * ev = arg ;
 int len ;
 len = read ( fd , rbuf + roff , sizeof ( rbuf ) - roff ) ;
 if ( len == - 1 ) fprintf ( stderr , "%s: read\n" , __func__ ) ;
 if ( len <= 0 ) {
 if ( usepersist ) event_del ( ev ) ;
 return ;
 }
 roff += len ;
 if ( ! usepersist ) {
 if ( event_add ( ev , NULL ) == - 1 ) exit ( 1 ) ;
 }
 }

static int jpc_enc_encodemainbody ( jpc_enc_t * enc ) {
 int tileno ;
 int tilex ;
 int tiley ;
 int i ;
 jpc_sot_t * sot ;
 jpc_enc_tcmpt_t * comp ;
 jpc_enc_tcmpt_t * endcomps ;
 jpc_enc_band_t * band ;
 jpc_enc_band_t * endbands ;
 jpc_enc_rlvl_t * lvl ;
 int rlvlno ;
 jpc_qcc_t * qcc ;
 jpc_cod_t * cod ;
 int adjust ;
 int j ;
 int absbandno ;
 long numbytes ;
 long tilehdrlen ;
 long tilelen ;
 jpc_enc_tile_t * tile ;
 jpc_enc_cp_t * cp ;
 double rho ;
 int lyrno ;
 int cmptno ;
 int samestepsizes ;
 jpc_enc_ccp_t * ccps ;
 jpc_enc_tccp_t * tccp ;
 int bandno ;
 uint_fast32_t x ;
 uint_fast32_t y ;
 int mingbits ;
 int actualnumbps ;
 jpc_fix_t mxmag ;
 jpc_fix_t mag ;
 int numgbits ;
 cp = enc -> cp ;
 numbytes = 0 ;
 for ( tileno = 0 ;
 tileno < JAS_CAST ( int , cp -> numtiles ) ;
 ++ tileno ) {
 tilex = tileno % cp -> numhtiles ;
 tiley = tileno / cp -> numhtiles ;
 if ( ! ( enc -> curtile = jpc_enc_tile_create ( enc -> cp , enc -> image , tileno ) ) ) {
 abort ( ) ;
 }
 tile = enc -> curtile ;
 if ( jas_getdbglevel ( ) >= 10 ) {
 jpc_enc_dump ( enc ) ;
 }
 endcomps = & tile -> tcmpts [ tile -> numtcmpts ] ;
 for ( cmptno = 0 , comp = tile -> tcmpts ;
 cmptno < tile -> numtcmpts ;
 ++ cmptno , ++ comp ) {
 if ( ! cp -> ccps [ cmptno ] . sgnd ) {
 adjust = 1 << ( cp -> ccps [ cmptno ] . prec - 1 ) ;
 for ( i = 0 ;
 i < jas_matrix_numrows ( comp -> data ) ;
 ++ i ) {
 for ( j = 0 ;
 j < jas_matrix_numcols ( comp -> data ) ;
 ++ j ) {
 * jas_matrix_getref ( comp -> data , i , j ) -= adjust ;
 }
 }
 }
 }
 if ( ! tile -> intmode ) {
 endcomps = & tile -> tcmpts [ tile -> numtcmpts ] ;
 for ( comp = tile -> tcmpts ;
 comp != endcomps ;
 ++ comp ) {
 jas_matrix_asl ( comp -> data , JPC_FIX_FRACBITS ) ;
 }
 }
 switch ( tile -> mctid ) {
 case JPC_MCT_RCT : assert ( jas_image_numcmpts ( enc -> image ) == 3 ) ;
 jpc_rct ( tile -> tcmpts [ 0 ] . data , tile -> tcmpts [ 1 ] . data , tile -> tcmpts [ 2 ] . data ) ;
 break ;
 case JPC_MCT_ICT : assert ( jas_image_numcmpts ( enc -> image ) == 3 ) ;
 jpc_ict ( tile -> tcmpts [ 0 ] . data , tile -> tcmpts [ 1 ] . data , tile -> tcmpts [ 2 ] . data ) ;
 break ;
 default : break ;
 }
 for ( i = 0 ;
 i < jas_image_numcmpts ( enc -> image ) ;
 ++ i ) {
 comp = & tile -> tcmpts [ i ] ;
 jpc_tsfb_analyze ( comp -> tsfb , comp -> data ) ;
 }
 endcomps = & tile -> tcmpts [ tile -> numtcmpts ] ;
 for ( cmptno = 0 , comp = tile -> tcmpts ;
 comp != endcomps ;
 ++ cmptno , ++ comp ) {
 mingbits = 0 ;
 absbandno = 0 ;
 memset ( comp -> stepsizes , 0 , sizeof ( comp -> stepsizes ) ) ;
 for ( rlvlno = 0 , lvl = comp -> rlvls ;
 rlvlno < comp -> numrlvls ;
 ++ rlvlno , ++ lvl ) {
 if ( ! lvl -> bands ) {
 absbandno += rlvlno ? 3 : 1 ;
 continue ;
 }
 endbands = & lvl -> bands [ lvl -> numbands ] ;
 for ( band = lvl -> bands ;
 band != endbands ;
 ++ band ) {
 if ( ! band -> data ) {
 ++ absbandno ;
 continue ;
 }
 actualnumbps = 0 ;
 mxmag = 0 ;
 for ( y = 0 ;
 y < JAS_CAST ( uint_fast32_t , jas_matrix_numrows ( band -> data ) ) ;
 ++ y ) {
 for ( x = 0 ;
 x < JAS_CAST ( uint_fast32_t , jas_matrix_numcols ( band -> data ) ) ;
 ++ x ) {
 mag = JAS_ABS ( jas_matrix_get ( band -> data , y , x ) ) ;
 if ( mag > mxmag ) {
 mxmag = mag ;
 }
 }
 }
 if ( tile -> intmode ) {
 actualnumbps = jpc_firstone ( mxmag ) + 1 ;
 }
 else {
 actualnumbps = jpc_firstone ( mxmag ) + 1 - JPC_FIX_FRACBITS ;
 }
 numgbits = actualnumbps - ( cp -> ccps [ cmptno ] . prec - 1 + band -> analgain ) ;
 # if 0 jas_eprintf ( "%d %d mag=%d actual=%d numgbits=%d\n" , cp -> ccps [ cmptno ] . prec , band -> analgain , mxmag , actualnumbps , numgbits ) ;
 # endif if ( numgbits > mingbits ) {
 mingbits = numgbits ;
 }
 if ( ! tile -> intmode ) {
 band -> absstepsize = jpc_fix_div ( jpc_inttofix ( 1 << ( band -> analgain + 1 ) ) , band -> synweight ) ;
 }
 else {
 band -> absstepsize = jpc_inttofix ( 1 ) ;
 }
 band -> stepsize = jpc_abstorelstepsize ( band -> absstepsize , cp -> ccps [ cmptno ] . prec + band -> analgain ) ;
 band -> numbps = cp -> tccp . numgbits + JPC_QCX_GETEXPN ( band -> stepsize ) - 1 ;
 if ( ( ! tile -> intmode ) && band -> data ) {
 jpc_quantize ( band -> data , band -> absstepsize ) ;
 }
 comp -> stepsizes [ absbandno ] = band -> stepsize ;
 ++ absbandno ;
 }
 }
 assert ( JPC_FIX_FRACBITS >= JPC_NUMEXTRABITS ) ;
 if ( ! tile -> intmode ) {
 jas_matrix_divpow2 ( comp -> data , JPC_FIX_FRACBITS - JPC_NUMEXTRABITS ) ;
 }
 else {
 jas_matrix_asl ( comp -> data , JPC_NUMEXTRABITS ) ;
 }
 # if 0 jas_eprintf ( "mingbits %d\n" , mingbits ) ;
 # endif if ( mingbits > cp -> tccp . numgbits ) {
 jas_eprintf ( "error: too few guard bits (need at least %d)\n" , mingbits ) ;
 return - 1 ;
 }
 }
 if ( ! ( enc -> tmpstream = jas_stream_memopen ( 0 , 0 ) ) ) {
 jas_eprintf ( "cannot open tmp file\n" ) ;
 return - 1 ;
 }
 if ( ! ( enc -> mrk = jpc_ms_create ( JPC_MS_SOT ) ) ) {
 return - 1 ;
 }
 sot = & enc -> mrk -> parms . sot ;
 sot -> len = 0 ;
 sot -> tileno = tileno ;
 sot -> partno = 0 ;
 sot -> numparts = 1 ;
 if ( jpc_putms ( enc -> tmpstream , enc -> cstate , enc -> mrk ) ) {
 jas_eprintf ( "cannot write SOT marker\n" ) ;
 return - 1 ;
 }
 jpc_ms_destroy ( enc -> mrk ) ;
 enc -> mrk = 0 ;
 tccp = & cp -> tccp ;
 for ( cmptno = 0 ;
 cmptno < JAS_CAST ( int , cp -> numcmpts ) ;
 ++ cmptno ) {
 comp = & tile -> tcmpts [ cmptno ] ;
 if ( comp -> numrlvls != tccp -> maxrlvls ) {
 if ( ! ( enc -> mrk = jpc_ms_create ( JPC_MS_COD ) ) ) {
 return - 1 ;
 }
 comp = & tile -> tcmpts [ 0 ] ;
 cod = & enc -> mrk -> parms . cod ;
 cod -> compparms . csty = 0 ;
 cod -> compparms . numdlvls = comp -> numrlvls - 1 ;
 cod -> prg = tile -> prg ;
 cod -> numlyrs = tile -> numlyrs ;
 cod -> compparms . cblkwidthval = JPC_COX_CBLKSIZEEXPN ( comp -> cblkwidthexpn ) ;
 cod -> compparms . cblkheightval = JPC_COX_CBLKSIZEEXPN ( comp -> cblkheightexpn ) ;
 cod -> compparms . cblksty = comp -> cblksty ;
 cod -> compparms . qmfbid = comp -> qmfbid ;
 cod -> mctrans = ( tile -> mctid != JPC_MCT_NONE ) ;
 for ( i = 0 ;
 i < comp -> numrlvls ;
 ++ i ) {
 cod -> compparms . rlvls [ i ] . parwidthval = comp -> rlvls [ i ] . prcwidthexpn ;
 cod -> compparms . rlvls [ i ] . parheightval = comp -> rlvls [ i ] . prcheightexpn ;
 }
 if ( jpc_putms ( enc -> tmpstream , enc -> cstate , enc -> mrk ) ) {
 return - 1 ;
 }
 jpc_ms_destroy ( enc -> mrk ) ;
 enc -> mrk = 0 ;
 }
 }
 for ( cmptno = 0 , comp = tile -> tcmpts ;
 cmptno < JAS_CAST ( int , cp -> numcmpts ) ;
 ++ cmptno , ++ comp ) {
 ccps = & cp -> ccps [ cmptno ] ;
 if ( JAS_CAST ( int , ccps -> numstepsizes ) == comp -> numstepsizes ) {
 samestepsizes = 1 ;
 for ( bandno = 0 ;
 bandno < JAS_CAST ( int , ccps -> numstepsizes ) ;
 ++ bandno ) {
 if ( ccps -> stepsizes [ bandno ] != comp -> stepsizes [ bandno ] ) {
 samestepsizes = 0 ;
 break ;
 }
 }
 }
 else {
 samestepsizes = 0 ;
 }
 if ( ! samestepsizes ) {
 if ( ! ( enc -> mrk = jpc_ms_create ( JPC_MS_QCC ) ) ) {
 return - 1 ;
 }
 qcc = & enc -> mrk -> parms . qcc ;
 qcc -> compno = cmptno ;
 qcc -> compparms . numguard = cp -> tccp . numgbits ;
 qcc -> compparms . qntsty = ( comp -> qmfbid == JPC_COX_INS ) ? JPC_QCX_SEQNT : JPC_QCX_NOQNT ;
 qcc -> compparms . numstepsizes = comp -> numstepsizes ;
 qcc -> compparms . stepsizes = comp -> stepsizes ;
 if ( jpc_putms ( enc -> tmpstream , enc -> cstate , enc -> mrk ) ) {
 return - 1 ;
 }
 qcc -> compparms . stepsizes = 0 ;
 jpc_ms_destroy ( enc -> mrk ) ;
 enc -> mrk = 0 ;
 }
 }
 if ( ! ( enc -> mrk = jpc_ms_create ( JPC_MS_SOD ) ) ) {
 return - 1 ;
 }
 if ( jpc_putms ( enc -> tmpstream , enc -> cstate , enc -> mrk ) ) {
 jas_eprintf ( "cannot write SOD marker\n" ) ;
 return - 1 ;
 }
 jpc_ms_destroy ( enc -> mrk ) ;
 enc -> mrk = 0 ;
 tilehdrlen = jas_stream_getrwcount ( enc -> tmpstream ) ;
 assert ( tilehdrlen >= 0 ) ;
 if ( jpc_enc_enccblks ( enc ) ) {
 abort ( ) ;
 return - 1 ;
 }
 cp = enc -> cp ;
 rho = ( double ) ( tile -> brx - tile -> tlx ) * ( tile -> bry - tile -> tly ) / ( ( cp -> refgrdwidth - cp -> imgareatlx ) * ( cp -> refgrdheight - cp -> imgareatly ) ) ;
 tile -> rawsize = cp -> rawsize * rho ;
 for ( lyrno = 0 ;
 lyrno < tile -> numlyrs - 1 ;
 ++ lyrno ) {
 tile -> lyrsizes [ lyrno ] = tile -> rawsize * jpc_fixtodbl ( cp -> tcp . ilyrrates [ lyrno ] ) ;
 }
 # if ! defined ( __clang__ ) tile -> lyrsizes [ tile -> numlyrs - 1 ] = ( cp -> totalsize != UINT_FAST32_MAX ) ? ( rho * enc -> mainbodysize ) : UINT_FAST32_MAX ;
 # else if ( cp -> totalsize != UINT_FAST32_MAX ) {
 tile -> lyrsizes [ tile -> numlyrs - 1 ] = ( rho * enc -> mainbodysize ) ;
 }
 else {
 tile -> lyrsizes [ tile -> numlyrs - 1 ] = UINT_FAST32_MAX ;
 }
 # endif for ( lyrno = 0 ;
 lyrno < tile -> numlyrs ;
 ++ lyrno ) {
 if ( tile -> lyrsizes [ lyrno ] != UINT_FAST32_MAX ) {
 if ( JAS_CAST ( uint_fast32_t , tilehdrlen ) <= tile -> lyrsizes [ lyrno ] ) {
 tile -> lyrsizes [ lyrno ] -= tilehdrlen ;
 }
 else {
 tile -> lyrsizes [ lyrno ] = 0 ;
 }
 }
 }
 if ( rateallocate ( enc , tile -> numlyrs , tile -> lyrsizes ) ) {
 return - 1 ;
 }
 # if 0 jas_eprintf ( "ENCODE TILE DATA\n" ) ;
 # endif if ( jpc_enc_encodetiledata ( enc ) ) {
 jas_eprintf ( "dotile failed\n" ) ;
 return - 1 ;
 }
 tilelen = jas_stream_tell ( enc -> tmpstream ) ;
 if ( jas_stream_seek ( enc -> tmpstream , 6 , SEEK_SET ) < 0 ) {
 return - 1 ;
 }
 jpc_putuint32 ( enc -> tmpstream , tilelen ) ;
 if ( jas_stream_seek ( enc -> tmpstream , 0 , SEEK_SET ) < 0 ) {
 return - 1 ;
 }
 if ( jpc_putdata ( enc -> out , enc -> tmpstream , - 1 ) ) {
 return - 1 ;
 }
 enc -> len += tilelen ;
 jas_stream_close ( enc -> tmpstream ) ;
 enc -> tmpstream = 0 ;
 jpc_enc_tile_destroy ( enc -> curtile ) ;
 enc -> curtile = 0 ;
 }
 return 0 ;
 }

static int ulti_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 const uint8_t * buf = avpkt -> data ;
 int buf_size = avpkt -> size ;
 UltimotionDecodeContext * s = avctx -> priv_data ;
 int modifier = 0 ;
 int uniq = 0 ;
 int mode = 0 ;
 int blocks = 0 ;
 int done = 0 ;
 int x = 0 , y = 0 ;
 int i ;
 int skip ;
 int tmp ;
 s -> frame . reference = 1 ;
 s -> frame . buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE ;
 if ( avctx -> reget_buffer ( avctx , & s -> frame ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "reget_buffer() failed\n" ) ;
 return - 1 ;
 }
 bytestream2_init ( & s -> gb , buf , buf_size ) ;
 while ( ! done ) {
 int idx ;
 if ( blocks >= s -> blocks || y >= s -> height ) break ;
 if ( bytestream2_get_bytes_left ( & s -> gb ) < 1 ) goto err ;
 idx = bytestream2_get_byteu ( & s -> gb ) ;
 if ( ( idx & 0xF8 ) == 0x70 ) {
 switch ( idx ) {
 case 0x70 : modifier = bytestream2_get_byte ( & s -> gb ) ;
 if ( modifier > 1 ) av_log ( avctx , AV_LOG_INFO , "warning: modifier must be 0 or 1, got %i\n" , modifier ) ;
 break ;
 case 0x71 : uniq = 1 ;
 break ;
 case 0x72 : mode = ! mode ;
 break ;
 case 0x73 : done = 1 ;
 break ;
 case 0x74 : skip = bytestream2_get_byte ( & s -> gb ) ;
 if ( ( blocks + skip ) >= s -> blocks ) break ;
 blocks += skip ;
 x += skip * 8 ;
 while ( x >= s -> width ) {
 x -= s -> width ;
 y += 8 ;
 }
 break ;
 default : av_log ( avctx , AV_LOG_INFO , "warning: unknown escape 0x%02X\n" , idx ) ;
 }
 }
 else {
 int code ;
 int cf ;
 int angle = 0 ;
 uint8_t Y [ 4 ] ;
 int tx = 0 , ty = 0 ;
 int chroma = 0 ;
 if ( mode || uniq ) {
 uniq = 0 ;
 cf = 1 ;
 chroma = 0 ;
 }
 else {
 cf = 0 ;
 if ( idx ) {
 chroma = bytestream2_get_byte ( & s -> gb ) ;
 }
 }
 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 code = ( idx >> ( 6 - i * 2 ) ) & 3 ;
 if ( ! code ) continue ;
 if ( cf ) {
 chroma = bytestream2_get_byte ( & s -> gb ) ;
 }
 tx = x + block_coords [ i * 2 ] ;
 ty = y + block_coords [ ( i * 2 ) + 1 ] ;
 switch ( code ) {
 case 1 : tmp = bytestream2_get_byte ( & s -> gb ) ;
 angle = angle_by_index [ ( tmp >> 6 ) & 0x3 ] ;
 Y [ 0 ] = tmp & 0x3F ;
 Y [ 1 ] = Y [ 0 ] ;
 if ( angle ) {
 Y [ 2 ] = Y [ 0 ] + 1 ;
 if ( Y [ 2 ] > 0x3F ) Y [ 2 ] = 0x3F ;
 Y [ 3 ] = Y [ 2 ] ;
 }
 else {
 Y [ 2 ] = Y [ 0 ] ;
 Y [ 3 ] = Y [ 0 ] ;
 }
 break ;
 case 2 : if ( modifier ) {
 tmp = bytestream2_get_be24 ( & s -> gb ) ;
 Y [ 0 ] = ( tmp >> 18 ) & 0x3F ;
 Y [ 1 ] = ( tmp >> 12 ) & 0x3F ;
 Y [ 2 ] = ( tmp >> 6 ) & 0x3F ;
 Y [ 3 ] = tmp & 0x3F ;
 angle = 16 ;
 }
 else {
 tmp = bytestream2_get_be16 ( & s -> gb ) ;
 angle = ( tmp >> 12 ) & 0xF ;
 tmp &= 0xFFF ;
 tmp <<= 2 ;
 Y [ 0 ] = s -> ulti_codebook [ tmp ] ;
 Y [ 1 ] = s -> ulti_codebook [ tmp + 1 ] ;
 Y [ 2 ] = s -> ulti_codebook [ tmp + 2 ] ;
 Y [ 3 ] = s -> ulti_codebook [ tmp + 3 ] ;
 }
 break ;
 case 3 : if ( modifier ) {
 uint8_t Luma [ 16 ] ;
 if ( bytestream2_get_bytes_left ( & s -> gb ) < 12 ) goto err ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 0 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 1 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 2 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 3 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 4 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 5 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 6 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 7 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 8 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 9 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 10 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 11 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 12 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 13 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 14 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 15 ] = tmp & 0x3F ;
 ulti_convert_yuv ( & s -> frame , tx , ty , Luma , chroma ) ;
 }
 else {
 if ( bytestream2_get_bytes_left ( & s -> gb ) < 4 ) goto err ;
 tmp = bytestream2_get_byteu ( & s -> gb ) ;
 if ( tmp & 0x80 ) {
 angle = ( tmp >> 4 ) & 0x7 ;
 tmp = ( tmp << 8 ) + bytestream2_get_byteu ( & s -> gb ) ;
 Y [ 0 ] = ( tmp >> 6 ) & 0x3F ;
 Y [ 1 ] = tmp & 0x3F ;
 Y [ 2 ] = bytestream2_get_byteu ( & s -> gb ) & 0x3F ;
 Y [ 3 ] = bytestream2_get_byteu ( & s -> gb ) & 0x3F ;
 ulti_grad ( & s -> frame , tx , ty , Y , chroma , angle ) ;
 }
 else {
 int f0 , f1 ;
 f0 = bytestream2_get_byteu ( & s -> gb ) ;
 f1 = tmp ;
 Y [ 0 ] = bytestream2_get_byteu ( & s -> gb ) & 0x3F ;
 Y [ 1 ] = bytestream2_get_byteu ( & s -> gb ) & 0x3F ;
 ulti_pattern ( & s -> frame , tx , ty , f1 , f0 , Y [ 0 ] , Y [ 1 ] , chroma ) ;
 }
 }
 break ;
 }
 if ( code != 3 ) ulti_grad ( & s -> frame , tx , ty , Y , chroma , angle ) ;
 }
 blocks ++ ;
 x += 8 ;
 if ( x >= s -> width ) {
 x = 0 ;
 y += 8 ;
 }
 }
 }
 * got_frame = 1 ;
 * ( AVFrame * ) data = s -> frame ;
 return buf_size ;
 err : av_log ( avctx , AV_LOG_ERROR , "Insufficient data\n" ) ;
 return AVERROR_INVALIDDATA ;
 }

int main ( int argc , char * argv [ ] ) {
 static char buff [ 16384 ] ;
 struct cpio _cpio ;
 struct cpio * cpio ;
 const char * errmsg ;
 int uid , gid ;
 int opt ;
 cpio = & _cpio ;
 memset ( cpio , 0 , sizeof ( * cpio ) ) ;
 cpio -> buff = buff ;
 cpio -> buff_size = sizeof ( buff ) ;
 # if defined ( HAVE_SIGACTION ) && defined ( SIGPIPE ) {
 struct sigaction sa ;
 sigemptyset ( & sa . sa_mask ) ;
 sa . sa_flags = 0 ;
 sa . sa_handler = SIG_IGN ;
 sigaction ( SIGPIPE , & sa , NULL ) ;
 }
 # endif lafe_setprogname ( * argv , "bsdcpio" ) ;
 # if HAVE_SETLOCALE if ( setlocale ( LC_ALL , "" ) == NULL ) lafe_warnc ( 0 , "Failed to set default locale" ) ;
 # endif cpio -> uid_override = - 1 ;
 cpio -> gid_override = - 1 ;
 cpio -> argv = argv ;
 cpio -> argc = argc ;
 cpio -> mode = '\0' ;
 cpio -> verbose = 0 ;
 cpio -> compress = '\0' ;
 cpio -> extract_flags = ARCHIVE_EXTRACT_NO_AUTODIR ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_NO_OVERWRITE_NEWER ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_SECURE_SYMLINKS ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_SECURE_NODOTDOT ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_SECURE_NOABSOLUTEPATHS ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_PERM ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_FFLAGS ;
 cpio -> extract_flags |= ARCHIVE_EXTRACT_ACL ;
 # if ! defined ( _WIN32 ) && ! defined ( __CYGWIN__ ) if ( geteuid ( ) == 0 ) cpio -> extract_flags |= ARCHIVE_EXTRACT_OWNER ;
 # endif cpio -> bytes_per_block = 512 ;
 cpio -> filename = NULL ;
 cpio -> matching = archive_match_new ( ) ;
 if ( cpio -> matching == NULL ) lafe_errc ( 1 , 0 , "Out of memory" ) ;
 while ( ( opt = cpio_getopt ( cpio ) ) != - 1 ) {
 switch ( opt ) {
 case '0' : cpio -> option_null = 1 ;
 break ;
