 vp9_wb_write_literal ( wb , lf -> sharpness_level , 3 ) ;
 vp9_wb_write_bit ( wb , lf -> mode_ref_delta_enabled ) ;
 if ( lf -> mode_ref_delta_enabled ) {
 vp9_wb_write_bit ( wb , lf -> mode_ref_delta_update ) ;
 if ( lf -> mode_ref_delta_update ) {
