static int ar_parse_gnu_filename_table ( struct archive_read * a ) {
 struct ar * ar ;
 char * p ;
 size_t size ;
 ar = ( struct ar * ) ( a -> format -> data ) ;
 size = ar -> strtab_size ;
 for ( p = ar -> strtab ;
 p < ar -> strtab + size - 1 ;
 ++ p ) {
 if ( * p == '/' ) {
 * p ++ = '\0' ;
 if ( * p != '\n' ) goto bad_string_table ;
 * p = '\0' ;
 }
 }
 if ( p != ar -> strtab + size && * p != '\n' && * p != '`' ) goto bad_string_table ;
 ar -> strtab [ size - 1 ] = '\0' ;
 return ( ARCHIVE_OK ) ;
 bad_string_table : archive_set_error ( & a -> archive , EINVAL , "Invalid string table" ) ;
 free ( ar -> strtab ) ;
 ar -> strtab = NULL ;
 return ( ARCHIVE_FATAL ) ;
 }

static char * quote_name ( const char * name , char * buff , my_bool force ) {
 char * to = buff ;
 char qtype = ( opt_compatible_mode & MASK_ANSI_QUOTES ) ? '\"' : '`' ;
 if ( ! force && ! opt_quoted && ! test_if_special_chars ( name ) ) return ( char * ) name ;
 * to ++ = qtype ;
 while ( * name ) {
 if ( * name == qtype ) * to ++ = qtype ;
 * to ++ = * name ++ ;
 }
 to [ 0 ] = qtype ;
 to [ 1 ] = 0 ;
 return buff ;
 }

