static int decode_residuals ( FLACContext * s , int32_t * decoded , int pred_order ) {
 int i , tmp , partition , method_type , rice_order ;
 int rice_bits , rice_esc ;
 int samples ;
 method_type = get_bits ( & s -> gb , 2 ) ;
 if ( method_type > 1 ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "illegal residual coding method %d\n" , method_type ) ;
 return - 1 ;
 }
 rice_order = get_bits ( & s -> gb , 4 ) ;
 samples = s -> blocksize >> rice_order ;
 if ( pred_order > samples ) {
 av_log ( s -> avctx , AV_LOG_ERROR , "invalid predictor order: %i > %i\n" , pred_order , samples ) ;
 return - 1 ;
 }
 rice_bits = 4 + method_type ;
 rice_esc = ( 1 << rice_bits ) - 1 ;
 decoded += pred_order ;
 i = pred_order ;
 for ( partition = 0 ;
 partition < ( 1 << rice_order ) ;
 partition ++ ) {
 tmp = get_bits ( & s -> gb , rice_bits ) ;
 if ( tmp == rice_esc ) {
 tmp = get_bits ( & s -> gb , 5 ) ;
 for ( ;
 i < samples ;
 i ++ ) * decoded ++ = get_sbits_long ( & s -> gb , tmp ) ;
 }
 else {
 for ( ;
 i < samples ;
 i ++ ) {
 * decoded ++ = get_sr_golomb_flac ( & s -> gb , tmp , INT_MAX , 0 ) ;
 }
 }
 i = 0 ;
 }
 return 0 ;
 }

static int generate_bits_table ( uint32_t * dst , const uint8_t * len_table ) {
 int len , index ;
 uint32_t bits = 0 ;
 for ( len = 32 ;
 len > 0 ;
 len -- ) {
 for ( index = 0 ;
 index < 256 ;
 index ++ ) {
 if ( len_table [ index ] == len ) dst [ index ] = bits ++ ;
 }
 if ( bits & 1 ) {
 av_log ( NULL , AV_LOG_ERROR , "Error generating huffman table\n" ) ;
 return - 1 ;
 }
 bits >>= 1 ;
 }
 return 0 ;
 }

static inline int copy_block ( AVCodecContext * avctx , uint8_t * to , uint8_t * from , int offset , int height , int stride ) {
 int i ;
 int width = height ;
 int from_x = offset % WIDTH ;
 int from_y = offset / WIDTH ;
 int overflow = from_x + width - WIDTH ;
 if ( ! from ) {
 return 0 ;
 }
 if ( from_y + height > HEIGHT ) {
 av_log ( avctx , AV_LOG_ERROR , "invalid offset %d during C93 decoding\n" , offset ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( overflow > 0 ) {
 width -= overflow ;
 for ( i = 0 ;
 i < height ;
 i ++ ) {
 memcpy ( & to [ i * stride + width ] , & from [ ( from_y + i ) * stride ] , overflow ) ;
 }
 }
 for ( i = 0 ;
 i < height ;
 i ++ ) {
 memcpy ( & to [ i * stride ] , & from [ ( from_y + i ) * stride + from_x ] , width ) ;
 }
 return 0 ;
 }

