 }
 action = buf + pos ;
 while ( pos < len && ( ! isspace ( ( unsigned char ) buf [ pos ] ) && buf [ pos ] != ':' ) ) pos ++ ;
 buf [ pos ] = '\0' ;
 return action ;
 }

