static int DecodeAsn1BuildValue ( const unsigned char * * d_ptr , uint32_t * val , uint8_t numbytes , uint32_t * errcode ) {
 int i ;
 uint32_t value = 0 ;
 if ( numbytes > 4 ) {
 if ( errcode ) * errcode = ERR_DER_INVALID_SIZE ;
 value = 0xffffffff ;
 * val = value ;
 return - 1 ;
 }
 else {
 for ( i = 0 ;
 i < numbytes ;
 i ++ ) {
 value = value << 8 | ( * d_ptr ) [ 0 ] ;
 ( * d_ptr ) ++ ;
 }
 }
 * val = value ;
 return 0 ;
 }

static int selinux_inode_setsecurity ( struct inode * inode , const char * name , const void * value , size_t size , int flags ) {
 struct inode_security_struct * isec = inode_security_novalidate ( inode ) ;
 u32 newsid ;
 int rc ;
 if ( strcmp ( name , XATTR_SELINUX_SUFFIX ) ) return - EOPNOTSUPP ;
 if ( ! value || ! size ) return - EACCES ;
 rc = security_context_to_sid ( value , size , & newsid , GFP_KERNEL ) ;
 if ( rc ) return rc ;
 spin_lock ( & isec -> lock ) ;
 isec -> sclass = inode_mode_to_security_class ( inode -> i_mode ) ;
 isec -> sid = newsid ;
 isec -> initialized = LABEL_INITIALIZED ;
 spin_unlock ( & isec -> lock ) ;
 return 0 ;
 }

