static uint64_t openpic_gbl_read ( void * opaque , hwaddr addr , unsigned len ) {
 OpenPICState * opp = opaque ;
 uint32_t retval ;
 DPRINTF ( "%s: addr %#" HWADDR_PRIx "\n" , __func__ , addr ) ;
 retval = 0xFFFFFFFF ;
 if ( addr & 0xF ) {
 return retval ;
 }
 switch ( addr ) {
 case 0x1000 : retval = opp -> frr ;
 break ;
 case 0x1020 : retval = opp -> gcr ;
 break ;
 case 0x1080 : retval = opp -> vir ;
 break ;
 case 0x1090 : retval = 0x00000000 ;
 break ;
 case 0x00 : retval = opp -> brr1 ;
 break ;
 case 0x40 : case 0x50 : case 0x60 : case 0x70 : case 0x80 : case 0x90 : case 0xA0 : case 0xB0 : retval = openpic_cpu_read_internal ( opp , addr , get_current_cpu ( ) ) ;
 break ;
 case 0x10A0 : case 0x10B0 : case 0x10C0 : case 0x10D0 : {
 int idx ;
 idx = ( addr - 0x10A0 ) >> 4 ;
 retval = read_IRQreg_ivpr ( opp , opp -> irq_ipi0 + idx ) ;
 }
 break ;
 case 0x10E0 : retval = opp -> spve ;
 break ;
 default : break ;
 }
 DPRINTF ( "%s: => 0x%08x\n" , __func__ , retval ) ;
 return retval ;
 }

static uint64_t nvic_sysreg_read ( void * opaque , hwaddr addr , unsigned size ) {
 nvic_state * s = ( nvic_state * ) opaque ;
 uint32_t offset = addr ;
 int i ;
 uint32_t val ;
 switch ( offset ) {
 case 0xd18 ... 0xd23 : val = 0 ;
 for ( i = 0 ;
 i < size ;
 i ++ ) {
 val |= s -> gic . priority1 [ ( offset - 0xd14 ) + i ] [ 0 ] << ( i * 8 ) ;
 }
 return val ;
 case 0xfe0 ... 0xfff : if ( offset & 3 ) {
 return 0 ;
 }
 return nvic_id [ ( offset - 0xfe0 ) >> 2 ] ;
 }
 if ( size == 4 ) {
 return nvic_readl ( s , offset ) ;
 }
 qemu_log_mask ( LOG_GUEST_ERROR , "NVIC: Bad read of size %d at offset 0x%x\n" , size , offset ) ;
 return 0 ;
 }

