 return ret ;
 }
 p += nalsize ;
 }
 cnt = * ( p ++ ) ;
 for ( i = 0 ;
 i < cnt ;
 i ++ ) {
 nalsize = AV_RB16 ( p ) + 2 ;
 if ( nalsize > size - ( p - buf ) ) return AVERROR_INVALIDDATA ;
 ret = decode_nal_units ( h , p , nalsize , 1 ) ;
 if ( ret < 0 ) {
