 rf -> frame_idx = pic_frame_idx ;
 ++ rf ;
 }
 }
 for ( ;
 rf < & render -> info . h264 . referenceFrames [ H264_RF_COUNT ] ;
 ++ rf ) {
 rf -> surface = VDP_INVALID_HANDLE ;
 rf -> is_long_term = 0 ;
 rf -> top_is_reference = 0 ;
