 const unsigned char * src_end = src + src_size ;
 memcpy ( huff_code_table , src , 15 ) ;
 src += 15 ;
 while ( src < src_end ) {
 huff_code = * src ++ ;
 if ( ( huff_code >> 4 ) == 15 ) {
 b = huff_code << 4 ;
 huff_code = * src ++ ;
 * dst_cur ++ = b | ( huff_code >> 4 ) ;
 }
 else * dst_cur ++ = huff_code_table [ huff_code >> 4 ] ;
 if ( dst_cur >= dst_end ) break ;
 huff_code &= 15 ;
 if ( huff_code == 15 ) {
 * dst_cur ++ = * src ++ ;
 }
 else * dst_cur ++ = huff_code_table [ huff_code ] ;
 if ( dst_cur >= dst_end ) break ;
 }
 return dst_cur - dst ;
 }

