static void residual_interp ( int16_t * buf , int16_t * out , int lag , int gain , int * rseed ) {
 int i ;
 if ( lag ) {
 int16_t * vector_ptr = buf + PITCH_MAX ;
 for ( i = 0 ;
 i < lag ;
 i ++ ) out [ i ] = vector_ptr [ i - lag ] * 3 >> 2 ;
 av_memcpy_backptr ( ( uint8_t * ) ( out + lag ) , lag * sizeof ( * out ) , ( FRAME_LEN - lag ) * sizeof ( * out ) ) ;
 }
 else {
 for ( i = 0 ;
 i < FRAME_LEN ;
 i ++ ) {
 * rseed = * rseed * 521 + 259 ;
 out [ i ] = gain * * rseed >> 15 ;
 }
 memset ( buf , 0 , ( FRAME_LEN + PITCH_MAX ) * sizeof ( * buf ) ) ;
 }
 }

static void forward_query ( int bind_fd , struct query * q ) {
 char buf [ 64 * 1024 ] ;
 int len ;
 struct fw_query fwq ;
 struct sockaddr_in * myaddr ;
 in_addr_t newaddr ;
 len = dns_encode ( buf , sizeof ( buf ) , q , QR_QUERY , q -> name , strlen ( q -> name ) ) ;
 if ( len < 1 ) {
 warnx ( "dns_encode doesn't fit" ) ;
 return ;
 }
 memcpy ( & ( fwq . addr ) , & ( q -> from ) , q -> fromlen ) ;
 fwq . addrlen = q -> fromlen ;
 fwq . id = q -> id ;
 fw_query_put ( & fwq ) ;
 newaddr = inet_addr ( "127.0.0.1" ) ;
 myaddr = ( struct sockaddr_in * ) & ( q -> from ) ;
 memcpy ( & ( myaddr -> sin_addr ) , & newaddr , sizeof ( in_addr_t ) ) ;
 myaddr -> sin_port = htons ( bind_port ) ;
 if ( debug >= 2 ) {
 fprintf ( stderr , "TX: NS reply \n" ) ;
 }
 if ( sendto ( bind_fd , buf , len , 0 , ( struct sockaddr * ) & q -> from , q -> fromlen ) <= 0 ) {
 warn ( "forward query error" ) ;
 }
 }

int nextvar ( int * datalen , const char * * datap , char * * vname , char * * vvalue ) {
 const char * cp ;
 const char * np ;
 const char * cpend ;
 size_t srclen ;
 size_t len ;
 static char name [ MAXVARLEN ] ;
 static char value [ MAXVALLEN ] ;
 cp = * datap ;
 cpend = cp + * datalen ;
 while ( cp < cpend && ( * cp == ',' || isspace ( ( int ) * cp ) ) ) cp ++ ;
 if ( cp >= cpend ) return 0 ;
 srclen = strcspn ( cp , ",=\r\n" ) ;
 srclen = min ( srclen , ( size_t ) ( cpend - cp ) ) ;
 len = srclen ;
 while ( len > 0 && isspace ( ( unsigned char ) cp [ len - 1 ] ) ) len -- ;
 if ( len > 0 ) memcpy ( name , cp , len ) ;
 name [ len ] = '\0' ;
 * vname = name ;
 cp += srclen ;
 if ( cp >= cpend || * cp == ',' || * cp == '\r' || * cp == '\n' ) {
 if ( cp < cpend ) cp ++ ;
 * datap = cp ;
 * datalen = cpend - cp ;
 * vvalue = NULL ;
 return 1 ;
 }
 cp ++ ;
 while ( cp < cpend && ( isspace ( ( unsigned char ) * cp ) && * cp != '\r' && * cp != '\n' ) ) cp ++ ;
 np = cp ;
 if ( '"' == * np ) {
 do {
 np ++ ;
 }
 while ( np < cpend && '"' != * np ) ;
 if ( np < cpend && '"' == * np ) np ++ ;
 }
 else {
 while ( np < cpend && ',' != * np && '\r' != * np ) np ++ ;
 }
 len = np - cp ;
 if ( np > cpend || len >= sizeof ( value ) || ( np < cpend && ',' != * np && '\r' != * np ) ) return 0 ;
 memcpy ( value , cp , len ) ;
 while ( len > 0 && isspace ( ( unsigned char ) value [ len - 1 ] ) ) len -- ;
 value [ len ] = '\0' ;
 if ( np < cpend && ',' == * np ) np ++ ;
 * datap = np ;
 * datalen = cpend - np ;
 * vvalue = value ;
 return 1 ;
 }

static struct kvm_cpuid2 * try_get_cpuid ( KVMState * s , int max ) {
 struct kvm_cpuid2 * cpuid ;
 int r , size ;
 size = sizeof ( * cpuid ) + max * sizeof ( * cpuid -> entries ) ;
 cpuid = g_malloc0 ( size ) ;
 cpuid -> nent = max ;
 r = kvm_ioctl ( s , KVM_GET_SUPPORTED_CPUID , cpuid ) ;
 if ( r == 0 && cpuid -> nent >= max ) {
 r = - E2BIG ;
 }
 if ( r < 0 ) {
 if ( r == - E2BIG ) {
 g_free ( cpuid ) ;
 return NULL ;
 }
 else {
 fprintf ( stderr , "KVM_GET_SUPPORTED_CPUID failed: %s\n" , strerror ( - r ) ) ;
 exit ( 1 ) ;
 }
 }
 return cpuid ;
 }

