 }
 }
 else {
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 if ( ! upgrade ) memcpy ( ptr , s -> bytestream , n ) ;
 else if ( upgrade == 1 ) {
 unsigned int j , f = ( 255 * 128 + s -> maxval / 2 ) / s -> maxval ;
 for ( j = 0 ;
 j < n ;
 j ++ ) ptr [ j ] = ( s -> bytestream [ j ] * f + 64 ) >> 7 ;
 }
 else if ( upgrade == 2 ) {
 unsigned int j , v , f = ( 65535 * 32768 + s -> maxval / 2 ) / s -> maxval ;
 for ( j = 0 ;
