 i < h ;
 i ++ ) {
 memcpy ( ptr1 , s -> bytestream , n ) ;
 s -> bytestream += n ;
 memcpy ( ptr2 , s -> bytestream , n ) ;
 s -> bytestream += n ;
 ptr1 += p -> linesize [ 1 ] ;
 ptr2 += p -> linesize [ 2 ] ;
