 ptr = p -> data [ 0 ] ;
 linesize = p -> linesize [ 0 ] ;
 if ( s -> bytestream + n * avctx -> height * 3 / 2 > s -> bytestream_end ) return AVERROR_INVALIDDATA ;
 for ( i = 0 ;
 i < avctx -> height ;
 i ++ ) {
 for ( j = 0 ;
 j < n / 2 ;
 j ++ ) {
 v = av_be2ne16 ( ( ( uint16_t * ) s -> bytestream ) [ j ] ) ;
