 ptr1 = ( uint16_t * ) p -> data [ 1 ] ;
 ptr2 = ( uint16_t * ) p -> data [ 2 ] ;
 n >>= 1 ;
 h = avctx -> height >> 1 ;
 for ( i = 0 ;
 i < h ;
 i ++ ) {
 for ( j = 0 ;
 j < n / 2 ;
 j ++ ) {
 v = av_be2ne16 ( ( ( uint16_t * ) s -> bytestream ) [ j ] ) ;
 ptr1 [ j ] = ( v * f + 16384 ) >> 15 ;
 }
 s -> bytestream += n ;
 for ( j = 0 ;
 j < n / 2 ;
 j ++ ) {
 v = av_be2ne16 ( ( ( uint16_t * ) s -> bytestream ) [ j ] ) ;
 ptr2 [ j ] = ( v * f + 16384 ) >> 15 ;
