 t = dst [ out - stride ] + ( table [ ( c * 2 ) + 1 ] - 128 ) ;
 t = av_clip_uint8 ( t ) ;
 dst [ out ] = t ;
 out ++ ;
 }
 }
 dst += stride ;
 }
 return 0 ;
 }

