static void apply_pitch_filters ( QCELPContext * q , float * cdn_vector ) {
 int i ;
 const float * v_synthesis_filtered , * v_pre_filtered ;
 if ( q -> bitrate >= RATE_HALF || q -> bitrate == SILENCE || ( q -> bitrate == I_F_Q && ( q -> prev_bitrate >= RATE_HALF ) ) ) {
 if ( q -> bitrate >= RATE_HALF ) {
 for ( i = 0 ;
 i < 4 ;
 i ++ ) {
 q -> pitch_gain [ i ] = q -> frame . plag [ i ] ? ( q -> frame . pgain [ i ] + 1 ) * 0.25 : 0.0 ;
 q -> pitch_lag [ i ] = q -> frame . plag [ i ] + 16 ;
 }
 }
 else {
 float max_pitch_gain ;
 if ( q -> bitrate == I_F_Q ) {
 if ( q -> erasure_count < 3 ) max_pitch_gain = 0.9 - 0.3 * ( q -> erasure_count - 1 ) ;
 else max_pitch_gain = 0.0 ;
 }
 else {
 assert ( q -> bitrate == SILENCE ) ;
 max_pitch_gain = 1.0 ;
 }
 for ( i = 0 ;
 i < 4 ;
 i ++ ) q -> pitch_gain [ i ] = FFMIN ( q -> pitch_gain [ i ] , max_pitch_gain ) ;
 memset ( q -> frame . pfrac , 0 , sizeof ( q -> frame . pfrac ) ) ;
 }
 v_synthesis_filtered = do_pitchfilter ( q -> pitch_synthesis_filter_mem , cdn_vector , q -> pitch_gain , q -> pitch_lag , q -> frame . pfrac ) ;
 for ( i = 0 ;
 i < 4 ;
 i ++ ) q -> pitch_gain [ i ] = 0.5 * FFMIN ( q -> pitch_gain [ i ] , 1.0 ) ;
 v_pre_filtered = do_pitchfilter ( q -> pitch_pre_filter_mem , v_synthesis_filtered , q -> pitch_gain , q -> pitch_lag , q -> frame . pfrac ) ;
 apply_gain_ctrl ( cdn_vector , v_synthesis_filtered , v_pre_filtered ) ;
 }
 else {
 memcpy ( q -> pitch_synthesis_filter_mem , cdn_vector + 17 , 143 * sizeof ( float ) ) ;
 memcpy ( q -> pitch_pre_filter_mem , cdn_vector + 17 , 143 * sizeof ( float ) ) ;
 memset ( q -> pitch_gain , 0 , sizeof ( q -> pitch_gain ) ) ;
 memset ( q -> pitch_lag , 0 , sizeof ( q -> pitch_lag ) ) ;
 }
 }

static void wmapro_window ( WMAProDecodeCtx * s ) {
 int i ;
 for ( i = 0 ;
 i < s -> channels_for_cur_subframe ;
 i ++ ) {
 int c = s -> channel_indexes_for_cur_subframe [ i ] ;
 float * window ;
 int winlen = s -> channel [ c ] . prev_block_len ;
 float * start = s -> channel [ c ] . coeffs - ( winlen >> 1 ) ;
 if ( s -> subframe_len < winlen ) {
 start += ( winlen - s -> subframe_len ) >> 1 ;
 winlen = s -> subframe_len ;
 }
 window = s -> windows [ av_log2 ( winlen ) - WMAPRO_BLOCK_MIN_BITS ] ;
 winlen >>= 1 ;
 s -> fdsp . vector_fmul_window ( start , start , start + winlen , window , winlen ) ;
 s -> channel [ c ] . prev_block_len = s -> subframe_len ;
 }
 }

static void mclms_update ( WmallDecodeCtx * s , int icoef , int * pred ) {
 int i , j , ich , pred_error ;
 int order = s -> mclms_order ;
 int num_channels = s -> num_channels ;
 int range = 1 << ( s -> bits_per_sample - 1 ) ;
 for ( ich = 0 ;
 ich < num_channels ;
 ich ++ ) {
 pred_error = s -> channel_residues [ ich ] [ icoef ] - pred [ ich ] ;
 if ( pred_error > 0 ) {
 for ( i = 0 ;
 i < order * num_channels ;
 i ++ ) s -> mclms_coeffs [ i + ich * order * num_channels ] += s -> mclms_updates [ s -> mclms_recent + i ] ;
 for ( j = 0 ;
 j < ich ;
 j ++ ) {
 if ( s -> channel_residues [ j ] [ icoef ] > 0 ) s -> mclms_coeffs_cur [ ich * num_channels + j ] += 1 ;
 else if ( s -> channel_residues [ j ] [ icoef ] < 0 ) s -> mclms_coeffs_cur [ ich * num_channels + j ] -= 1 ;
 }
 }
 else if ( pred_error < 0 ) {
 for ( i = 0 ;
 i < order * num_channels ;
 i ++ ) s -> mclms_coeffs [ i + ich * order * num_channels ] -= s -> mclms_updates [ s -> mclms_recent + i ] ;
 for ( j = 0 ;
 j < ich ;
 j ++ ) {
 if ( s -> channel_residues [ j ] [ icoef ] > 0 ) s -> mclms_coeffs_cur [ ich * num_channels + j ] -= 1 ;
 else if ( s -> channel_residues [ j ] [ icoef ] < 0 ) s -> mclms_coeffs_cur [ ich * num_channels + j ] += 1 ;
 }
 }
 }
 for ( ich = num_channels - 1 ;
 ich >= 0 ;
 ich -- ) {
 s -> mclms_recent -- ;
 s -> mclms_prevvalues [ s -> mclms_recent ] = s -> channel_residues [ ich ] [ icoef ] ;
 if ( s -> channel_residues [ ich ] [ icoef ] > range - 1 ) s -> mclms_prevvalues [ s -> mclms_recent ] = range - 1 ;
 else if ( s -> channel_residues [ ich ] [ icoef ] < - range ) s -> mclms_prevvalues [ s -> mclms_recent ] = - range ;
 s -> mclms_updates [ s -> mclms_recent ] = 0 ;
 if ( s -> channel_residues [ ich ] [ icoef ] > 0 ) s -> mclms_updates [ s -> mclms_recent ] = 1 ;
 else if ( s -> channel_residues [ ich ] [ icoef ] < 0 ) s -> mclms_updates [ s -> mclms_recent ] = - 1 ;
 }
 if ( s -> mclms_recent == 0 ) {
 memcpy ( & s -> mclms_prevvalues [ order * num_channels ] , s -> mclms_prevvalues , 2 * order * num_channels ) ;
 memcpy ( & s -> mclms_updates [ order * num_channels ] , s -> mclms_updates , 2 * order * num_channels ) ;
 s -> mclms_recent = num_channels * order ;
 }
 }

static void truespeech_correlate_filter ( TSContext * dec ) {
 int16_t tmp [ 8 ] ;
 int i , j ;
 for ( i = 0 ;
 i < 8 ;
 i ++ ) {
 if ( i > 0 ) {
 memcpy ( tmp , dec -> cvector , i * sizeof ( * tmp ) ) ;
 for ( j = 0 ;
 j < i ;
 j ++ ) dec -> cvector [ j ] = ( ( tmp [ i - j - 1 ] * dec -> vector [ i ] ) + ( dec -> cvector [ j ] << 15 ) + 0x4000 ) >> 15 ;
 }
 dec -> cvector [ i ] = ( 8 - dec -> vector [ i ] ) >> 3 ;
 }
 for ( i = 0 ;
 i < 8 ;
 i ++ ) dec -> cvector [ i ] = ( dec -> cvector [ i ] * ts_decay_994_1000 [ i ] ) >> 15 ;
 dec -> filtval = dec -> vector [ 0 ] ;
 }

