 break ;
 case 0x71 : uniq = 1 ;
 break ;
 case 0x72 : mode = ! mode ;
 break ;
 case 0x73 : done = 1 ;
 break ;
 case 0x74 : skip = bytestream2_get_byte ( & s -> gb ) ;
 if ( ( blocks + skip ) >= s -> blocks ) break ;
 blocks += skip ;
 x += skip * 8 ;
