 Luma [ 1 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 2 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 3 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
