 ctx -> cur = ctx -> frm1 ;
 ctx -> prev = ctx -> frm0 ;
 }
 else {
 ctx -> cur = ctx -> frm0 ;
 ctx -> prev = ctx -> frm1 ;
 }
 * got_frame = 1 ;
 return avpkt -> size ;
 }

static int vb_decode_framedata ( VBDecContext * c , int offset ) {
