 break ;
 case 0x40 : t = bytestream2_get_byte ( & g ) ;
 if ( ! t ) {
 if ( bytestream2_get_bytes_left ( & g ) < 16 ) {
 av_log ( c -> avctx , AV_LOG_ERROR , "Insufficient data\n" ) ;
