 }
 for ( y = 0 ;
 y < 4 ;
 y ++ ) bytestream2_get_buffer ( & g , cur + y * width , 4 ) ;
 }
 else {
 x = ( ( t & 0xF ) ^ 8 ) - 8 ;
 y = ( ( t >> 4 ) ^ 8 ) - 8 ;
 t = x + y * width ;
 for ( y = 0 ;
 y < 4 ;
 y ++ ) if ( check_line ( prev + t + y * width , pstart , pend ) ) memcpy ( cur + y * width , prev + t + y * width , 4 ) ;
