 }
 break ;
 case 0x80 : t = bytestream2_get_byte ( & g ) ;
 for ( y = 0 ;
 y < 4 ;
 y ++ ) memset ( cur + y * width , t , 4 ) ;
 break ;
 case 0xC0 : t = bytestream2_get_byte ( & g ) ;
 pattype = t >> 6 ;
