 }
 blocktypes <<= 2 ;
 cur += 4 ;
 prev += 4 ;
 blk2 ++ ;
 if ( blk2 == ( width >> 2 ) ) {
 blk2 = 0 ;
 cur += width * 3 ;
 prev += width * 3 ;
 }
 }
 return 0 ;
 }

