static void config_logconfig ( config_tree * ptree ) {
 attr_val * my_lc ;
 my_lc = HEAD_PFIFO ( ptree -> logconfig ) ;
 for ( ;
 my_lc != NULL ;
 my_lc = my_lc -> link ) {
 switch ( my_lc -> attr ) {
 case '+' : ntp_syslogmask |= get_logmask ( my_lc -> value . s ) ;
 break ;
 case '-' : ntp_syslogmask &= ~ get_logmask ( my_lc -> value . s ) ;
 break ;
 case '=' : ntp_syslogmask = get_logmask ( my_lc -> value . s ) ;
 break ;
 }
 }
 }

int ssl_version_supported ( const SSL * s , int version ) {
 const version_info * vent ;
 const version_info * table ;
 switch ( s -> method -> version ) {
 default : return version_cmp ( s , version , s -> version ) == 0 ;
 case TLS_ANY_VERSION : table = tls_version_table ;
 break ;
 case DTLS_ANY_VERSION : table = dtls_version_table ;
 break ;
 }
 for ( vent = table ;
 vent -> version != 0 && version_cmp ( s , version , vent -> version ) <= 0 ;
 ++ vent ) {
 if ( vent -> cmeth != NULL && version_cmp ( s , version , vent -> version ) == 0 && ssl_method_error ( s , vent -> cmeth ( ) ) == 0 ) {
 return 1 ;
 }
 }
 return 0 ;
 }

script_info * create_sim_script_info ( double duration , attr_val_fifo * script_queue ) {
 # ifndef SIM return NULL ;
 # else script_info * my_info ;
 attr_val * my_attr_val ;
 my_info = emalloc_zero ( sizeof ( * my_info ) ) ;
 my_info -> duration = duration ;
 my_info -> prop_delay = NET_DLY ;
 my_info -> proc_delay = PROC_DLY ;
 for ( my_attr_val = HEAD_PFIFO ( script_queue ) ;
 my_attr_val != NULL ;
 my_attr_val = my_attr_val -> link ) {
 switch ( my_attr_val -> attr ) {
 case T_Freq_Offset : my_info -> freq_offset = my_attr_val -> value . d ;
 break ;
 case T_Wander : my_info -> wander = my_attr_val -> value . d ;
 break ;
 case T_Jitter : my_info -> jitter = my_attr_val -> value . d ;
 break ;
 case T_Prop_Delay : my_info -> prop_delay = my_attr_val -> value . d ;
 break ;
 case T_Proc_Delay : my_info -> proc_delay = my_attr_val -> value . d ;
 break ;
 default : msyslog ( LOG_ERR , "Unknown script token %d" , my_attr_val -> attr ) ;
 }
 }
 return my_info ;
 # endif }

static uint64_t nvic_sysreg_read ( void * opaque , hwaddr addr , unsigned size ) {
 nvic_state * s = ( nvic_state * ) opaque ;
 uint32_t offset = addr ;
 int i ;
 uint32_t val ;
 switch ( offset ) {
 case 0xd18 ... 0xd23 : val = 0 ;
 for ( i = 0 ;
 i < size ;
 i ++ ) {
 val |= s -> gic . priority1 [ ( offset - 0xd14 ) + i ] [ 0 ] << ( i * 8 ) ;
 }
 return val ;
 case 0xfe0 ... 0xfff : if ( offset & 3 ) {
 return 0 ;
 }
 return nvic_id [ ( offset - 0xfe0 ) >> 2 ] ;
 }
 if ( size == 4 ) {
 return nvic_readl ( s , offset ) ;
 }
 qemu_log_mask ( LOG_GUEST_ERROR , "NVIC: Bad read of size %d at offset 0x%x\n" , size , offset ) ;
 return 0 ;
 }

static int fts_build_full_words ( struct fts_mail_build_context * ctx , const unsigned char * data , size_t size , bool last ) {
 size_t i ;
 if ( ctx -> word_buf != NULL && ctx -> word_buf -> used > 0 ) {
 for ( i = 0 ;
 i < size ;
 i ++ ) {
 if ( IS_WORD_WHITESPACE ( data [ i ] ) ) break ;
 }
 buffer_append ( ctx -> word_buf , data , i ) ;
 data += i ;
 size -= i ;
 if ( size == 0 && ctx -> word_buf -> used < MAX_WORD_SIZE && ! last ) {
 return 0 ;
 }
 if ( fts_backend_update_build_more ( ctx -> update_ctx , ctx -> word_buf -> data , ctx -> word_buf -> used ) < 0 ) return - 1 ;
 buffer_set_used_size ( ctx -> word_buf , 0 ) ;
 }
 if ( last ) i = size ;
 else {
 for ( i = size ;
 i > 0 ;
 i -- ) {
 if ( IS_WORD_WHITESPACE ( data [ i - 1 ] ) ) break ;
 }
 }
 if ( fts_backend_update_build_more ( ctx -> update_ctx , data , i ) < 0 ) return - 1 ;
 if ( i < size ) {
 if ( ctx -> word_buf == NULL ) {
 ctx -> word_buf = buffer_create_dynamic ( default_pool , 128 ) ;
 }
 buffer_append ( ctx -> word_buf , data + i , size - i ) ;
 }
 return 0 ;
 }

bool message_search_more_get_decoded ( struct message_search_context * ctx , struct message_block * raw_block , struct message_block * decoded_block_r ) {
 struct message_header_line * hdr = raw_block -> hdr ;
 struct message_block decoded_block ;
 i_zero ( decoded_block_r ) ;
 decoded_block_r -> part = raw_block -> part ;
 if ( raw_block -> part != ctx -> prev_part ) {
 message_search_reset ( ctx ) ;
 ctx -> prev_part = raw_block -> part ;
 if ( hdr == NULL ) {
 ctx -> content_type_text = FALSE ;
 }
 }
 if ( hdr != NULL ) {
 handle_header ( ctx , hdr ) ;
 if ( ( ctx -> flags & MESSAGE_SEARCH_FLAG_SKIP_HEADERS ) != 0 ) {
 if ( hdr -> name_len != 12 && hdr -> name_len != 25 ) return FALSE ;
 if ( strcasecmp ( hdr -> name , "Content-Type" ) != 0 && strcasecmp ( hdr -> name , "Content-Transfer-Encoding" ) != 0 ) return FALSE ;
 }
 }
 else {
 if ( ! ctx -> content_type_text ) return FALSE ;
 }
 if ( ! message_decoder_decode_next_block ( ctx -> decoder , raw_block , & decoded_block ) ) return FALSE ;
 if ( decoded_block . hdr != NULL && ( ctx -> flags & MESSAGE_SEARCH_FLAG_SKIP_HEADERS ) != 0 ) {
 return FALSE ;
 }
 * decoded_block_r = decoded_block ;
 return message_search_more_decoded2 ( ctx , & decoded_block ) ;
 }

static int fts_build_unstructured_header ( struct fts_mail_build_context * ctx , const struct message_header_line * hdr ) {
 const unsigned char * data = hdr -> full_value ;
 unsigned char * buf = NULL ;
 unsigned int i ;
 int ret ;
 for ( i = 0 ;
 i < hdr -> full_value_len ;
 i ++ ) {
 if ( data [ i ] == '\0' ) {
 if ( buf == NULL ) {
 buf = i_malloc ( hdr -> full_value_len ) ;
 memcpy ( buf , data , i ) ;
 data = buf ;
 }
 buf [ i ] = ' ' ;
 }
 else if ( buf != NULL ) {
 buf [ i ] = data [ i ] ;
 }
 }
 ret = fts_build_data ( ctx , data , hdr -> full_value_len , TRUE ) ;
 i_free ( buf ) ;
 return ret ;
 }

static int config_connection_request ( struct config_connection * conn , const char * const * args ) {
 struct config_export_context * ctx ;
 struct master_service_settings_output output ;
 struct config_filter filter ;
 const char * path , * error , * module , * const * wanted_modules ;
 ARRAY ( const char * ) modules ;
 bool is_master = FALSE ;
 t_array_init ( & modules , 4 ) ;
 i_zero ( & filter ) ;
 for ( ;
 * args != NULL ;
 args ++ ) {
 if ( strncmp ( * args , "service=" , 8 ) == 0 ) filter . service = * args + 8 ;
 else if ( strncmp ( * args , "module=" , 7 ) == 0 ) {
 module = * args + 7 ;
 if ( strcmp ( module , "master" ) == 0 ) is_master = TRUE ;
 array_append ( & modules , & module , 1 ) ;
 }
 else if ( strncmp ( * args , "lname=" , 6 ) == 0 ) filter . local_name = * args + 6 ;
 else if ( strncmp ( * args , "lip=" , 4 ) == 0 ) {
 if ( net_addr2ip ( * args + 4 , & filter . local_net ) == 0 ) {
 filter . local_bits = IPADDR_IS_V4 ( & filter . local_net ) ? : 128 ;
 }
 }
 else if ( strncmp ( * args , "rip=" , 4 ) == 0 ) {
 if ( net_addr2ip ( * args + 4 , & filter . remote_net ) == 0 ) {
 filter . remote_bits = IPADDR_IS_V4 ( & filter . remote_net ) ? : 128 ;
 }
 }
 }
 array_append_zero ( & modules ) ;
 wanted_modules = array_count ( & modules ) == 1 ? NULL : array_idx ( & modules , 0 ) ;
 if ( is_master ) {
 path = master_service_get_config_path ( master_service ) ;
 if ( config_parse_file ( path , TRUE , NULL , & error ) <= 0 ) {
 o_stream_nsend_str ( conn -> output , t_strconcat ( "\nERROR " , error , "\n" , NULL ) ) ;
 config_connection_destroy ( conn ) ;
 return - 1 ;
 }
 }
 o_stream_cork ( conn -> output ) ;
 ctx = config_export_init ( wanted_modules , CONFIG_DUMP_SCOPE_SET , 0 , config_request_output , conn -> output ) ;
 config_export_by_filter ( ctx , & filter ) ;
 config_export_get_output ( ctx , & output ) ;
 if ( output . specific_services != NULL ) {
 const char * const * s ;
 for ( s = output . specific_services ;
 * s != NULL ;
 s ++ ) {
 o_stream_nsend_str ( conn -> output , t_strdup_printf ( "service=%s\t" , * s ) ) ;
