 ctx -> prev_part = raw_block -> part ;
 if ( hdr == NULL ) {
 ctx -> content_type_text = FALSE ;
 }
 }
 if ( hdr != NULL ) {
 handle_header ( ctx , hdr ) ;
 if ( ( ctx -> flags & MESSAGE_SEARCH_FLAG_SKIP_HEADERS ) != 0 ) {
