 i < hdr -> full_value_len ;
 i ++ ) {
 if ( data [ i ] == '\0' ) {
 if ( buf == NULL ) {
 buf = i_malloc ( hdr -> full_value_len ) ;
 memcpy ( buf , data , i ) ;
 data = buf ;
 }
 buf [ i ] = ' ' ;
