 if ( mode || uniq ) {
 uniq = 0 ;
 cf = 1 ;
 chroma = 0 ;
 }
 else {
 cf = 0 ;
 if ( idx ) {
 chroma = bytestream2_get_byte ( & s -> gb ) ;
 }
 }
