 Luma [ 1 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 2 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 3 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 4 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 5 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 6 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 7 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
 Luma [ 8 ] = ( tmp >> 18 ) & 0x3F ;
 Luma [ 9 ] = ( tmp >> 12 ) & 0x3F ;
 Luma [ 10 ] = ( tmp >> 6 ) & 0x3F ;
 Luma [ 11 ] = tmp & 0x3F ;
 tmp = bytestream2_get_be24u ( & s -> gb ) ;
