void vp8_mbpost_proc_across_ip_c ( unsigned char * src , int pitch , int rows , int cols , int flimit ) {
 int r , c , i ;
 unsigned char * s = src ;
 unsigned char d [ 16 ] ;
 for ( r = 0 ;
 r < rows ;
 r ++ ) {
 int sumsq = 0 ;
 int sum = 0 ;
 for ( i = - 8 ;
 i < 0 ;
 i ++ ) s [ i ] = s [ 0 ] ;
 for ( i = cols ;
 i < cols + 17 ;
 i ++ ) s [ i ] = s [ cols - 1 ] ;
 for ( i = - 8 ;
 i <= 6 ;
 i ++ ) {
 sumsq += s [ i ] * s [ i ] ;
 sum += s [ i ] ;
 d [ i + 8 ] = 0 ;
 }
 for ( c = 0 ;
 c < cols + 8 ;
 c ++ ) {
 int x = s [ c + 7 ] - s [ c - 8 ] ;
 int y = s [ c + 7 ] + s [ c - 8 ] ;
 sum += x ;
 sumsq += x * y ;
 d [ c & 15 ] = s [ c ] ;
 if ( sumsq * 15 - sum * sum < flimit ) {
 d [ c & 15 ] = ( 8 + sum + s [ c ] ) >> 4 ;
 }
 s [ c - 8 ] = d [ ( c - 8 ) & 15 ] ;
 }
 s += pitch ;
 }
 }

void gx_device_set_margins ( gx_device * dev , const float * margins , bool move_origin ) {
 int i ;
 for ( i = 0 ;
 i < 4 ;
 ++ i ) dev -> HWMargins [ i ] = margins [ i ] * 72.0 ;
 if ( move_origin ) {
 dev -> Margins [ 0 ] = - margins [ 0 ] * dev -> HWResolution [ 0 ] ;
 dev -> Margins [ 1 ] = - margins [ 3 ] * dev -> HWResolution [ 1 ] ;
 }
 }

static inline int unreference_pic ( H264Context * h , Picture * pic , int refmask ) {
 int i ;
 if ( pic -> reference &= refmask ) {
 return 0 ;
 }
 else {
 for ( i = 0 ;
 h -> delayed_pic [ i ] ;
 i ++ ) if ( pic == h -> delayed_pic [ i ] ) {
 pic -> reference = DELAYED_PIC_REF ;
 break ;
 }
 return 1 ;
 }
 }

static void sbr_chirp ( SpectralBandReplication * sbr , SBRData * ch_data ) {
 int i ;
 float new_bw ;
 static const float bw_tab [ ] = {
 0.0f , 0.75f , 0.9f , 0.98f }
 ;
 for ( i = 0 ;
 i < sbr -> n_q ;
 i ++ ) {
 if ( ch_data -> bs_invf_mode [ 0 ] [ i ] + ch_data -> bs_invf_mode [ 1 ] [ i ] == 1 ) {
 new_bw = 0.6f ;
 }
 else new_bw = bw_tab [ ch_data -> bs_invf_mode [ 0 ] [ i ] ] ;
 if ( new_bw < ch_data -> bw_array [ i ] ) {
 new_bw = 0.75f * new_bw + 0.25f * ch_data -> bw_array [ i ] ;
 }
 else new_bw = 0.90625f * new_bw + 0.09375f * ch_data -> bw_array [ i ] ;
 ch_data -> bw_array [ i ] = new_bw < 0.015625f ? 0.0f : new_bw ;
 }
 }

