 c -> channels = avctx -> channels ;
 c -> header_parsed = 1 ;
 if ( buf_size < header_size ) return AVERROR_INVALIDDATA ;
 buf += header_size ;
 buf_size -= header_size ;
 }
 if ( ! c -> header_parsed ) return AVERROR_INVALIDDATA ;
