 samples_offset = 0 ;
 while ( num_blocks -- ) {
 for ( ch = 0 ;
 ch < c -> channels ;
 ch ++ ) {
 if ( adx_decode ( c , samples [ ch ] , samples_offset , buf , ch ) ) {
 c -> eof = 1 ;
