int ff_ivi_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 IVI45DecContext * ctx = avctx -> priv_data ;
 const uint8_t * buf = avpkt -> data ;
 int buf_size = avpkt -> size ;
 int result , p , b ;
 init_get_bits ( & ctx -> gb , buf , buf_size * 8 ) ;
 ctx -> frame_data = buf ;
 ctx -> frame_size = buf_size ;
 result = ctx -> decode_pic_hdr ( ctx , avctx ) ;
 if ( result ) {
 av_log ( avctx , AV_LOG_ERROR , "Error while decoding picture header: %d\n" , result ) ;
 return - 1 ;
 }
 if ( ctx -> gop_invalid ) return AVERROR_INVALIDDATA ;
 if ( ctx -> gop_flags & IVI5_IS_PROTECTED ) {
 av_log ( avctx , AV_LOG_ERROR , "Password-protected clip!\n" ) ;
 return - 1 ;
 }
 ctx -> switch_buffers ( ctx ) ;
 if ( ctx -> is_nonnull_frame ( ctx ) ) {
 for ( p = 0 ;
 p < 3 ;
 p ++ ) {
 for ( b = 0 ;
 b < ctx -> planes [ p ] . num_bands ;
 b ++ ) {
 result = decode_band ( ctx , & ctx -> planes [ p ] . bands [ b ] , avctx ) ;
 if ( result ) {
 av_log ( avctx , AV_LOG_ERROR , "Error while decoding band: %d, plane: %d\n" , b , p ) ;
 return - 1 ;
 }
 }
 }
 }
 if ( avctx -> codec_id == AV_CODEC_ID_INDEO4 && ctx -> frame_type == 0 ) {
 while ( get_bits ( & ctx -> gb , 8 ) ) ;
 skip_bits_long ( & ctx -> gb , 64 ) ;
 if ( get_bits_left ( & ctx -> gb ) > 18 && show_bits ( & ctx -> gb , 18 ) == 0x3FFF8 ) av_log ( avctx , AV_LOG_ERROR , "Buffer contains IP frames!\n" ) ;
 }
 if ( ctx -> frame . data [ 0 ] ) avctx -> release_buffer ( avctx , & ctx -> frame ) ;
 ctx -> frame . reference = 0 ;
 avcodec_set_dimensions ( avctx , ctx -> planes [ 0 ] . width , ctx -> planes [ 0 ] . height ) ;
 if ( ( result = ff_get_buffer ( avctx , & ctx -> frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return result ;
 }
 if ( ctx -> is_scalable ) {
 if ( avctx -> codec_id == AV_CODEC_ID_INDEO4 ) ff_ivi_recompose_haar ( & ctx -> planes [ 0 ] , ctx -> frame . data [ 0 ] , ctx -> frame . linesize [ 0 ] ) ;
 else ff_ivi_recompose53 ( & ctx -> planes [ 0 ] , ctx -> frame . data [ 0 ] , ctx -> frame . linesize [ 0 ] ) ;
 }
 else {
 ivi_output_plane ( & ctx -> planes [ 0 ] , ctx -> frame . data [ 0 ] , ctx -> frame . linesize [ 0 ] ) ;
 }
 ivi_output_plane ( & ctx -> planes [ 2 ] , ctx -> frame . data [ 1 ] , ctx -> frame . linesize [ 1 ] ) ;
 ivi_output_plane ( & ctx -> planes [ 1 ] , ctx -> frame . data [ 2 ] , ctx -> frame . linesize [ 2 ] ) ;
 * got_frame = 1 ;
 * ( AVFrame * ) data = ctx -> frame ;
 return buf_size ;
 }

static int decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
 JvContext * s = avctx -> priv_data ;
 int buf_size = avpkt -> size ;
 const uint8_t * buf = avpkt -> data ;
 const uint8_t * buf_end = buf + buf_size ;
 int video_size , video_type , i , j , ret ;
 video_size = AV_RL32 ( buf ) ;
 video_type = buf [ 4 ] ;
 buf += 5 ;
 if ( video_size ) {
 if ( ( ret = ff_reget_buffer ( avctx , & s -> frame ) ) < 0 ) {
 av_log ( avctx , AV_LOG_ERROR , "get_buffer() failed\n" ) ;
 return ret ;
 }
 if ( video_type == 0 || video_type == 1 ) {
 GetBitContext gb ;
 init_get_bits ( & gb , buf , 8 * FFMIN ( video_size , buf_end - buf ) ) ;
 for ( j = 0 ;
 j < avctx -> height ;
 j += 8 ) for ( i = 0 ;
 i < avctx -> width ;
 i += 8 ) decode8x8 ( & gb , s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] + i , s -> frame . linesize [ 0 ] , & s -> dsp ) ;
 buf += video_size ;
 }
 else if ( video_type == 2 ) {
 if ( buf + 1 <= buf_end ) {
 int v = * buf ++ ;
 for ( j = 0 ;
 j < avctx -> height ;
 j ++ ) memset ( s -> frame . data [ 0 ] + j * s -> frame . linesize [ 0 ] , v , avctx -> width ) ;
 }
 }
 else {
 av_log ( avctx , AV_LOG_WARNING , "unsupported frame type %i\n" , video_type ) ;
 return AVERROR_INVALIDDATA ;
 }
 }
 if ( buf < buf_end ) {
 for ( i = 0 ;
 i < AVPALETTE_COUNT && buf + 3 <= buf_end ;
 i ++ ) {
 s -> palette [ i ] = AV_RB24 ( buf ) << 2 ;
 buf += 3 ;
 }
 s -> palette_has_changed = 1 ;
 }
 if ( video_size ) {
 s -> frame . key_frame = 1 ;
 s -> frame . pict_type = AV_PICTURE_TYPE_I ;
 s -> frame . palette_has_changed = s -> palette_has_changed ;
 s -> palette_has_changed = 0 ;
 memcpy ( s -> frame . data [ 1 ] , s -> palette , AVPALETTE_SIZE ) ;
 if ( ( ret = av_frame_ref ( data , & s -> frame ) ) < 0 ) return ret ;
 * got_frame = 1 ;
 }
 return buf_size ;
 }

static int vcr1_decode_frame ( AVCodecContext * avctx , void * data , int * got_frame , AVPacket * avpkt ) {
