 p -> pict_type = AV_PICTURE_TYPE_I ;
 p -> key_frame = 1 ;
 for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 a -> delta [ i ] = * bytestream ++ ;
 bytestream ++ ;
 }
 for ( y = 0 ;
 y < avctx -> height ;
 y ++ ) {
