static void pxa2xx_fir_rx ( void * opaque , const uint8_t * buf , int size ) {
 PXA2xxFIrState * s = ( PXA2xxFIrState * ) opaque ;
 if ( ! ( s -> control [ 0 ] & ( 1 << 4 ) ) ) return ;
 while ( size -- ) {
 s -> status [ 1 ] |= 1 << 4 ;
 if ( s -> rx_len >= 64 ) {
 s -> status [ 1 ] |= 1 << 6 ;
 break ;
 }
 if ( s -> control [ 2 ] & ( 1 << 3 ) ) s -> rx_fifo [ ( s -> rx_start + s -> rx_len ++ ) & 63 ] = * ( buf ++ ) ;
 else s -> rx_fifo [ ( s -> rx_start + s -> rx_len ++ ) & 63 ] = ~ * ( buf ++ ) ;
 }
 pxa2xx_fir_update ( s ) ;
 }

static char * php_zip_make_relative_path ( char * path , int path_len ) {
 char * path_begin = path ;
 size_t i ;
 if ( path_len < 1 || path == NULL ) {
 return NULL ;
 }
 if ( IS_SLASH ( path [ 0 ] ) ) {
 return path + 1 ;
 }
 i = path_len ;
 while ( 1 ) {
 while ( i > 0 && ! IS_SLASH ( path [ i ] ) ) {
 i -- ;
 }
 if ( ! i ) {
 return path ;
 }
 if ( i >= 2 && ( path [ i - 1 ] == '.' || path [ i - 1 ] == ':' ) ) {
 path_begin = path + i + 1 ;
 break ;
 }
 i -- ;
 }
 return path_begin ;
 }

