 const UPropsVectors * pv = ( const UPropsVectors * ) context ;
 int32_t i , count , columns ;
 count = columns = pv -> columns ;
 i = 2 ;
 do {
 if ( left [ i ] != right [ i ] ) {
 return left [ i ] < right [ i ] ? - 1 : 1 ;
