static int ar_parse_gnu_filename_table ( struct archive_read * a ) {
 struct ar * ar ;
 char * p ;
 size_t size ;
 ar = ( struct ar * ) ( a -> format -> data ) ;
 size = ar -> strtab_size ;
 for ( p = ar -> strtab ;
 p < ar -> strtab + size - 1 ;
 ++ p ) {
 if ( * p == '/' ) {
 * p ++ = '\0' ;
 if ( * p != '\n' ) goto bad_string_table ;
 * p = '\0' ;
 }
 }
 if ( p != ar -> strtab + size && * p != '\n' && * p != '`' ) goto bad_string_table ;
 ar -> strtab [ size - 1 ] = '\0' ;
 return ( ARCHIVE_OK ) ;
 bad_string_table : archive_set_error ( & a -> archive , EINVAL , "Invalid string table" ) ;
 free ( ar -> strtab ) ;
 ar -> strtab = NULL ;
 return ( ARCHIVE_WARN ) ;
 }

static int write_to_temp ( struct archive_write * a , const void * buff , size_t s ) {
 struct iso9660 * iso9660 = a -> format_data ;
 ssize_t written ;
 const unsigned char * b ;
 b = ( const unsigned char * ) buff ;
 while ( s ) {
 written = write ( iso9660 -> temp_fd , b , s ) ;
 if ( written < 0 ) {
 archive_set_error ( & a -> archive , errno , "Can't write to temporary file" ) ;
 return ( ARCHIVE_FATAL ) ;
 }
 s -= written ;
 b += written ;
 }
 return ( ARCHIVE_OK ) ;
 }

static int archive_read_format_cpio_read_data ( struct archive_read * a , const void * * buff , size_t * size , int64_t * offset ) {
 ssize_t bytes_read ;
 struct cpio * cpio ;
 cpio = ( struct cpio * ) ( a -> format -> data ) ;
 if ( cpio -> entry_bytes_unconsumed ) {
 __archive_read_consume ( a , cpio -> entry_bytes_unconsumed ) ;
 cpio -> entry_bytes_unconsumed = 0 ;
 }
 if ( cpio -> entry_bytes_remaining > 0 ) {
 * buff = __archive_read_ahead ( a , 1 , & bytes_read ) ;
 if ( bytes_read <= 0 ) return ( ARCHIVE_FATAL ) ;
 if ( bytes_read > cpio -> entry_bytes_remaining ) bytes_read = ( ssize_t ) cpio -> entry_bytes_remaining ;
 * size = bytes_read ;
 cpio -> entry_bytes_unconsumed = bytes_read ;
 * offset = cpio -> entry_offset ;
 cpio -> entry_offset += bytes_read ;
 cpio -> entry_bytes_remaining -= bytes_read ;
 return ( ARCHIVE_OK ) ;
 }
 else {
 if ( cpio -> entry_padding != __archive_read_consume ( a , cpio -> entry_padding ) ) {
 return ( ARCHIVE_FATAL ) ;
 }
 cpio -> entry_padding = 0 ;
 * buff = NULL ;
 * size = 0 ;
 * offset = cpio -> entry_offset ;
 return ( ARCHIVE_EOF ) ;
 }
 }

static int archive_read_format_cpio_skip ( struct archive_read * a ) {
 struct cpio * cpio = ( struct cpio * ) ( a -> format -> data ) ;
 int64_t to_skip = cpio -> entry_bytes_remaining + cpio -> entry_padding + cpio -> entry_bytes_unconsumed ;
 if ( to_skip != __archive_read_consume ( a , to_skip ) ) {
 return ( ARCHIVE_FATAL ) ;
 }
 cpio -> entry_bytes_remaining = 0 ;
 cpio -> entry_padding = 0 ;
 cpio -> entry_bytes_unconsumed = 0 ;
 return ( ARCHIVE_OK ) ;
 }

