 switch ( token & 3 ) {
 case 0 : if ( -- token < 4 ) s -> dct_tokens [ plane ] [ i ] ++ ;
 else * s -> dct_tokens [ plane ] [ i ] = token & ~ 3 ;
 goto end ;
 case 1 : s -> dct_tokens [ plane ] [ i ] ++ ;
 i += ( token >> 2 ) & 0x7f ;
 if ( i > 63 ) {
