 return i ;
 }
 block [ perm [ i ] ] = ( token >> 9 ) * dequantizer [ perm [ i ] ] ;
 i ++ ;
 break ;
 case 2 : block [ perm [ i ] ] = ( token >> 2 ) * dequantizer [ perm [ i ] ] ;
 s -> dct_tokens [ plane ] [ i ++ ] ++ ;
 break ;
 default : return i ;
 }
 }
 while ( i < 64 ) ;
 i -- ;
 end : block [ 0 ] = frag -> dc * s -> qmat [ 0 ] [ inter ] [ plane ] [ 0 ] ;
